var PATH_BOOK_CHEM = {"subject": "化学", "book": "必修第一册", "version": "鲁科版", "chapters": [{"no": 1, "title": "认识化学科学", "units": ["u_chem_1", "u_chem_2", "u_chem_3", "u_chem_4", "u_chem_5", "u_chem_6", "u_chem_7"]}, {"no": 2, "title": "元素与物质世界", "units": ["u_chem_8", "u_chem_9", "u_chem_10", "u_chem_11", "u_chem_12", "u_chem_13", "u_chem_14"]}], "order": ["u_chem_1", "u_chem_2", "u_chem_3", "u_chem_4", "u_chem_5", "u_chem_6", "u_chem_7", "u_chem_8", "u_chem_9", "u_chem_10", "u_chem_11", "u_chem_12", "u_chem_13", "u_chem_14"], "nodes": {"chem_c001": {"name": "化学科学的形成与发展", "sec": 1, "secTitle": "走进化学科学", "page": 2, "desc": "从元素概念、质量守恒到原子论、分子学说和元素周期表——五位科学家、五级台阶。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c002"], "content": {"advance": {"a": "因为他用定量实验的方法推翻燃素说、提出质量守恒定律，使化学从定性描述走向定量科学。", "kind": "self", "q": "用一句话说清：为什么说拉瓦锡是「近代化学之父」？（提示：他改变了研究化学的方法）"}, "apply": [{"ans": 1, "opts": ["宏观水平", "原子、分子水平", "宇观水平", "细胞水平"], "q": "化学科学的定义强调研究的水平是（ ）", "why": "化学在原子、分子水平上研究物质，这是化学区别于物理、生物的标志。"}], "basics": [{"ans": 1, "opts": ["波义耳", "道尔顿", "阿伏加德罗", "门捷列夫"], "q": "提出原子论的科学家是（ ）", "why": "道尔顿提出原子论；阿伏加德罗提出的是分子学说。"}, {"ans": 1, "opts": ["工厂废气处理达标后排放", "设计不产生废物的新合成路线", "把废水稀释后排入河流", "垃圾集中焚烧"], "q": "下列做法属于「绿色化学」思想的是（ ）", "why": "绿色化学强调从源头消除污染，处理、稀释、焚烧都是末端治理。"}], "case": {"a": "A—⑤，B—④，C—①，D—②，E—③。", "hints": ["先想每个人最出名的那一件东西：周期表是谁的？", "原子和分子是两个人分开讲清的：一个讲原子存在，一个讲分子存在。"], "q": "连线题：A 波义耳 B 拉瓦锡 C 道尔顿 D 阿伏加德罗 E 门捷列夫；① 原子论 ② 分子学说 ③ 元素周期表 ④ 质量守恒定律 ⑤ 元素的概念。给出正确对应。", "steps": ["周期表最有名：E—③。", "质量守恒是近代化学的奠基实验：B—④。", "元素概念由波义耳提出：A—⑤。", "原子论归道尔顿：C—①；分子学说归阿伏加德罗：D—②。"], "talk": ["这类题只考对应关系，不考年份细节，把五组「人物—贡献」背成口诀：波元素、拉守恒、道原子、阿分子、门周期。"], "title": "案例：对号入座——五位科学家分别做了什么"}, "intro": "这一节不考计算，考的是「化学这门学问是怎么一步步长出来的」。==化学是在原子、分子水平上研究物质的组成、结构、性质、转化及其应用的一门基础学科。==记住这句定义，再记住五位关键人物分别贡献了什么，这一节的分就稳了。", "learn": [{"h": "五位人物，五级台阶", "p": "**波义耳**提出**元素**的概念，化学开始成为一门科学；**拉瓦锡**提出**质量守恒定律**，推翻燃素说；**道尔顿**提出**原子论**，解释了物质由原子构成。\n\n==一部化学史，就是人类认识物质从「定性猜测」走向「定量规律」的历史。==**阿伏加德罗**提出**分子学说**，区分了原子与分子；**门捷列夫**编制**元素周期表**，让元素有了秩序，还能预测新元素。"}, {"h": "现代化学的三大热点方向", "p": "教材点名的现代方向要记牢：**绿色化学**（从源头减少污染）、**纳米化学**、**超分子化学**。\n\n==绿色化学的核心是从源头上减少或消除污染，而不是先污染再治理。==考试常把「尾气处理后再排放」当作绿色化学来设陷阱——那是末端治理，不是绿色化学。"}, {"h": "化学科学的探索领域", "p": "化学主要在三个层面做事：发现或合成**新物质**、研究物质的**结构与性能关系**、研究化学反应的**规律与条件**。\n\n生活中处处是例子：新药研发是合成新物质，芯片材料是结构决定性能，催化剂是调控反应条件。"}, {"h": "易错提醒", "p": "易错提醒：道尔顿的是**原子论**、阿伏加德罗的是**分子学说**，人物和学说最容易张冠李戴；质量守恒定律的提出者是**拉瓦锡**，不是门捷列夫。"}], "pitfalls": ["原子论（道尔顿）与分子学说（阿伏加德罗）混淆。", "把末端治理误认为绿色化学。"], "svg": "<line x1='30' y1='70' x2='330' y2='70' stroke='#94a3b8' stroke-width='2'/><circle cx='50' cy='70' r='7' fill='#2563eb'/><circle cx='120' cy='70' r='7' fill='#2563eb'/><circle cx='190' cy='70' r='7' fill='#2563eb'/><circle cx='260' cy='70' r='7' fill='#2563eb'/><circle cx='325' cy='70' r='7' fill='#dc2626'/><text x='50' y='52' text-anchor='middle' font-size='12'>元素概念</text><text x='50' y='95' text-anchor='middle' font-size='11' fill='#64748b'>波义耳</text><text x='120' y='52' text-anchor='middle' font-size='12'>质量守恒</text><text x='120' y='95' text-anchor='middle' font-size='11' fill='#64748b'>拉瓦锡</text><text x='190' y='52' text-anchor='middle' font-size='12'>原子论</text><text x='190' y='95' text-anchor='middle' font-size='11' fill='#64748b'>道尔顿</text><text x='260' y='52' text-anchor='middle' font-size='12'>分子学说</text><text x='260' y='95' text-anchor='middle' font-size='11' fill='#64748b'>阿伏加德罗</text><text x='325' y='52' text-anchor='middle' font-size='12'>周期表</text><text x='325' y='95' text-anchor='middle' font-size='11' fill='#64748b'>门捷列夫</text>", "svgCap": "化学科学形成与发展的五级台阶：人物与贡献一一对应，是本节最高频考点。"}, "video": {"bvid": "BV11S4y1b7eE", "p": 1, "t": "走进化学科学", "dur": "15:21", "vtop": ["化学是在原子、分子水平上研究物质的学科。", "五位科学家对应五项贡献：元素概念、质量守恒、原子论、分子学说、周期表。", "绿色化学是从源头消除污染，不是末端治理。"], "vsum": "化学史就是五级台阶：波义耳给出元素的概念，拉瓦锡用定量实验确立**质量守恒**，道尔顿提出**原子论**，阿伏加德罗提出**分子学说**，门捷列夫排出周期表。现代方向记三个词：**绿色化学**（源头减污）、纳米化学、超分子化学。==考试爱考人物与贡献的对应==，以及把末端治理冒充绿色化学的陷阱。视频为化学僧鲁科版必修一《走进化学科学》（15:21）。\n易错提醒：绿色化学指的是从源头减少或消除污染，把末端治理说成绿色化学是这类题最常见的陷阱。", "vtech": ["看到「人物—贡献」连线信号 → 先锁定最有名的周期表（门捷列夫）和质量守恒（拉瓦锡），再排其余。", "看到「尾气/废水处理后排放」→ 判断为末端治理，不是绿色化学。"], "vgaokao": [], "from": 0}}, "chem_c002": {"name": "化学科学的探索与价值", "sec": 1, "secTitle": "走进化学科学", "page": 5, "desc": "化学创造新物质、开发新材料、助力能源环境与生命科学，绿色化学是现代方向。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c001"], "next": [], "content": {"advance": {"a": "示例：合成氨制化肥解决了粮食产量问题；青蒿素等合成/提取药物解决了疾病治疗问题；合成纤维解决了天然纤维不足的问题。言之有理即可。", "kind": "self", "q": "举一个生活中「化学创造的新物质改变生活」的例子，并说明它解决了什么问题。"}, "apply": [{"ans": 0, "opts": ["能源转化与储存", "药物合成", "农业增产", "食品防腐"], "q": "氢能汽车的储氢材料研究，主要体现化学在哪个领域的探索（ ）", "why": "储氢解决的是能源的储存与转化问题。"}], "basics": [{"ans": 1, "opts": ["合成药物", "新材料", "化肥增产", "食品添加"], "q": "芯片的核心材料属于化学贡献的哪个方向（ ）", "why": "半导体硅材料是典型的新材料方向。"}, {"ans": 1, "opts": ["化学品必然污染环境，应全面禁用", "造成污染的是不合理使用化学品", "环境治理与化学无关", "合成物质都不如天然物质"], "q": "下列说法正确的是（ ）", "why": "化学是双刃剑，合理使用造福人类，环境治理同样离不开化学。"}], "case": {"a": "体现创造新物质的价值，并服务于环境保护、践行绿色化学理念。", "hints": ["先归类：它在造什么新东西？", "可降解对应的是环境问题。"], "q": "新闻材料：「我国科学家合成出可降解塑料新单体，有望替代传统聚乙烯。」这则材料体现化学科学的哪方面价值？为什么可降解是关键？", "steps": ["合成新单体属于「创造新物质」。", "传统聚乙烯难降解造成白色污染，可降解意味着从材料设计源头减少污染。", "这同时呼应绿色化学思想。"], "talk": ["材料题三步走：找关键词→定类别→扣意义，别抄材料原句凑字数。"], "title": "案例：材料题怎么归类"}, "intro": "化学不只是造新物质，它还改变了我们的吃穿住行。这一节把教材列举的成就和化学的价值说清，考试多以选择题的材料形式出现——读懂材料、对应到「新物质／新材料／新能源／生命科学」哪一类即可。", "learn": [{"h": "化学创造新物质", "p": "人类发现和合成的物质已达上亿种。==化学的核心任务之一，就是创造自然界不存在的新物质。==化肥让粮食增产，合成药物挽救生命，合成纤维解决了穿衣问题。"}, {"h": "新材料与新能源", "p": "**半导体材料**（硅）撑起芯片产业，**高温超导材料**、**纳米材料**不断刷新性能上限；化学还参与开发**太阳能、氢能**等清洁能源的转化与储存。\n\n判断一道材料题属于哪类成就，先看材料里出现的是「药、肥料」还是「芯片、电池」。"}, {"h": "化学与生命、环境", "p": "化学帮助人类认识**生命过程**（如蛋白质、DNA 的结构与功能），也为**环境保护**提供监测与治理手段。\n\n易错提醒：化学品不是污染的代名词——不合理使用才造成污染，解决问题最终还要靠化学。"}], "pitfalls": ["把「化学品」与「污染」直接画等号。", "材料题只抄材料、不做归类。"], "svg": "<rect x='120' y='15' width='120' height='34' rx='8' fill='#2563eb'/><text x='180' y='37' text-anchor='middle' font-size='14' fill='#fff'>化学科学</text><rect x='15' y='85' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='65' y='105' text-anchor='middle' font-size='12'>新物质合成</text><rect x='130' y='85' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='180' y='105' text-anchor='middle' font-size='12'>新材料</text><rect x='245' y='85' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='295' y='105' text-anchor='middle' font-size='12'>能源与环境</text><line x1='120' y1='49' x2='65' y2='85' stroke='#94a3b8'/><line x1='180' y1='49' x2='180' y2='85' stroke='#94a3b8'/><line x1='240' y1='49' x2='295' y2='85' stroke='#94a3b8'/>", "svgCap": "化学科学的三大价值方向：合成新物质、开发新材料、解决能源与环境问题。"}, "video": {"bvid": "BV11S4y1b7eE", "p": 1, "t": "走进化学科学", "dur": "15:21", "vtop": ["化学是在原子、分子水平上研究物质的学科。", "五位科学家对应五项贡献：元素概念、质量守恒、原子论、分子学说、周期表。", "绿色化学是从源头消除污染，不是末端治理。"], "vsum": "化学史就是五级台阶：波义耳给出元素的概念，拉瓦锡用定量实验确立**质量守恒**，道尔顿提出**原子论**，阿伏加德罗提出**分子学说**，门捷列夫排出周期表。现代方向记三个词：**绿色化学**（源头减污）、纳米化学、超分子化学。==考试爱考人物与贡献的对应==，以及把末端治理冒充绿色化学的陷阱。视频为化学僧鲁科版必修一《走进化学科学》（15:21）。\n易错提醒：绿色化学指的是从源头减少或消除污染，把末端治理说成绿色化学是这类题最常见的陷阱。", "vtech": ["看到「人物—贡献」连线信号 → 先锁定最有名的周期表（门捷列夫）和质量守恒（拉瓦锡），再排其余。", "看到「尾气/废水处理后排放」→ 判断为末端治理，不是绿色化学。"], "vgaokao": [], "from": 0}}, "chem_c003": {"name": "研究物质性质的方法和程序", "sec": 2, "secTitle": "研究物质性质的方法和程序", "page": 10, "desc": "观察、实验、分类、比较四种方法；观察→预测→实验→结论的固定程序。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c004", "chem_c005", "chem_c011"], "content": {"advance": {"a": "预测决定实验的设计方向（验证什么、观察什么现象），没有预测的实验是盲目试错；预测放在实验后就失去指导意义，程序也就不存在了。", "kind": "self", "q": "为什么「预测」这一步不能省、也不能放在实验之后？"}, "apply": [{"ans": 2, "opts": ["观察法", "实验法", "分类法", "比较法中的定量测量"], "q": "「钠和钾同属碱金属，性质相似」这一预测主要运用了哪种方法（ ）", "why": "按类别归属、由已知类别的通性推测未知物质，属于分类的思想方法。"}], "basics": [{"ans": 1, "opts": ["实验→观察→预测→结论", "观察→预测→实验→结论", "预测→观察→实验→结论", "观察→实验→预测→结论"], "q": "研究物质性质的基本程序，正确的顺序是（ ）", "why": "先观察外部特征形成预测，再实验验证，最后解释得出结论。"}, {"ans": 1, "opts": ["把鼻子凑到瓶口深吸", "用手在瓶口轻轻扇动，飘闻少许", "打开瓶盖静置后远观", "先加热再闻"], "q": "闻氯气气味的正确方法是（ ）", "why": "飘闻法是闻任何未知气体气味的标准安全操作。"}], "case": {"a": "观察（黄绿色、刺激性气味、有毒）→预测（与金属、H₂、水反应）→实验（Cu、H₂、氯水漂白）→结论（性质活泼、强氧化性）。", "hints": ["观察：从试剂瓶和集气瓶看颜色、状态，查资料知道气味和毒性。", "预测：氯气是非金属单质，类比非金属通性。", "验证：与金属、氢气、水的反应实验。"], "q": "请按基本程序写出研究氯气性质的思路：先观察到什么、据此预测什么、用什么实验验证？", "steps": ["观察外部特征：氯气是黄绿色气体，有刺激性气味，有毒，密度比空气大，能溶于水。", "预测：作为活泼非金属单质，可能与多数金属反应、与氢气反应、与水反应。", "实验验证：铜丝在氯气中燃烧生成棕黄色烟；氢气在氯气中安静燃烧发出苍白色火焰；氯水使石蕊先变红后褪色。", "解释结论：氯气化学性质活泼，具有强氧化性。"], "talk": ["程序题就按四步模板作答，每一步都要落到具体物质上，空写步骤名不给分。"], "title": "案例：按程序研究氯气"}, "intro": "研究一种新物质，不能上来就乱试。教材给了四个基本方法：**观察、实验、分类、比较**，和一套固定程序。本节的真正考点是把这套程序用在钠和氯气两个具体案例上——方法和案例要绑在一起记。", "learn": [{"h": "四种基本方法", "p": "**观察**：有计划地记录物质的色、态、味和实验现象；**实验**：通过可控操作验证猜想；**分类**：按组成或性质归类，借已知推未知；**比较**：找异同、找规律。\n\n==四种方法不是并列清单，而是互相配合：观察提出问题，分类比较形成预测，实验负责验证。=="}, {"h": "研究物质性质的基本程序", "p": "固定四步：**观察物质的外部特征→预测物质的性质→进行实验和观察→解释并得出结论**。\n\n==程序的顺序不能乱：先观察、再预测，然后才动手实验。==考试爱把顺序打乱让你排序，或问「预测」这一步的依据是什么——依据是物质所属类别的通性和原子结构特点。"}, {"h": "预测从哪里来", "p": "预测不是瞎猜：一看**类别**（如氯气是非金属单质，可能与金属反应）；二看**结构**（如钠最外层 1 个电子，易失电子）。\n\n易错提醒：闻未知气体气味必须用**飘闻法**（用手轻轻扇动），绝不能凑近瓶口直接闻，氯气有毒更要注意。"}], "pitfalls": ["程序四步顺序记反（尤其预测与实验的先后）。", "闻气体直接凑近瓶口。"], "svg": "<rect x='10' y='50' width='78' height='34' rx='6' fill='#e0f2fe'/><text x='49' y='71' text-anchor='middle' font-size='12'>观察特征</text><rect x='102' y='50' width='78' height='34' rx='6' fill='#e0f2fe'/><text x='141' y='71' text-anchor='middle' font-size='12'>预测性质</text><rect x='194' y='50' width='78' height='34' rx='6' fill='#e0f2fe'/><text x='233' y='71' text-anchor='middle' font-size='12'>实验验证</text><rect x='286' y='50' width='78' height='34' rx='6' fill='#dbeafe'/><text x='325' y='71' text-anchor='middle' font-size='12'>解释结论</text><text x='95' y='71' font-size='13'>→</text><text x='187' y='71' font-size='13'>→</text><text x='279' y='71' font-size='13'>→</text><text x='185' y='30' text-anchor='middle' font-size='12' fill='#dc2626'>顺序不能颠倒</text>", "svgCap": "研究物质性质的基本程序：观察→预测→实验→结论。"}, "video": {"bvid": "BV1zK411674L", "p": 1, "t": "研究物质性质的方法和程序（一）", "dur": "20:47", "vtop": ["四种方法：观察、实验、分类、比较。", "基本程序：观察→预测→实验→结论，顺序不能乱。", "钠与氧气：常温 Na₂O（白色），加热 Na₂O₂（淡黄色）。"], "vsum": "方法四件套（观察、实验、分类、比较）加上固定程序（==观察→预测→实验→结论==），是研究任何新物质的通用打法。钠是第一个案例：保存在**煤油**中；常温被氧化成白色 **Na₂O**，加热生成淡黄色 **Na₂O₂**（氧为 −1 价，能与水、CO₂ 反应放氧，可作**供氧剂**）；与铁的比较说明金属有共性、更有个性。\n易错提醒：钠在常温下被氧化成白色 Na₂O、加热时生成淡黄色 Na₂O₂，两种产物的颜色一定要对应记准。", "vtech": ["看到排序题信号 → 默念「观察、预测、实验、结论」，预测永远在实验前。", "看到钠与氧气的题 → 先问条件：常温白色 Na₂O，加热淡黄 Na₂O₂。"], "vgaokao": [], "from": 0}}, "chem_c004": {"name": "金属钠的性质与过氧化钠", "sec": 2, "secTitle": "研究物质性质的方法和程序", "page": 12, "desc": "钠的保存、与氧气反应（常温 Na₂O/加热 Na₂O₂）、Na₂O 与 Na₂O₂ 的比较。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c003"], "next": [], "content": {"advance": {"a": "因为它能与人呼出的 CO₂ 和水蒸气反应放出 O₂：2Na₂O₂ + 2CO₂ ＝ 2Na₂CO₃ + O₂；2Na₂O₂ + 2H₂O ＝ 4NaOH + O₂↑。", "kind": "self", "q": "Na₂O₂ 为什么能用作潜水艇和呼吸面具的供氧剂？写出两个相关反应方程式。"}, "apply": [{"ans": 3, "opts": ["浮在水面——钠密度比水小", "熔成小球——反应放热且钠熔点低", "四处游动——生成气体推动", "溶液变红（滴有酚酞）——生成了酸性物质"], "q": "将小块钠投入水中，下列现象与解释对应错误的是（ ）", "why": "钠与水生成 NaOH 使溶液呈碱性，酚酞变红是因为碱性不是酸性。"}], "basics": [{"ans": 1, "opts": ["水中", "煤油中", "酒精中", "浓硫酸中"], "q": "实验室中金属钠通常保存在（ ）", "why": "钠不与煤油反应且密度比煤油大，可隔绝空气和水；钠与水、酒精都会反应。"}, {"ans": 1, "opts": ["白色，−2 价", "淡黄色，−1 价", "白色，−1 价", "淡黄色，−2 价"], "q": "Na₂O₂ 的颜色和氧元素的化合价分别是（ ）", "why": "Na₂O₂ 为淡黄色过氧化物，其中氧为 −1 价。"}], "case": {"a": "最终产物是 Na₂CO₃（碳酸钠）粉末。", "hints": ["第一步：常温与 O₂ 反应生成 Na₂O。", "第二步：Na₂O 吸水变 NaOH，NaOH 潮解后吸收 CO₂。", "最后：风化得到碳酸钠晶体再失水成粉末。"], "q": "一块金属钠长期露置在空气中，最终产物是什么？写出主要的变化过程。", "steps": ["4Na + O₂ ＝ 2Na₂O（切面变暗）。", "Na₂O + H₂O ＝ 2NaOH，NaOH 吸水潮解成溶液。", "2NaOH + CO₂ ＝ Na₂CO₃ + H₂O，得到 Na₂CO₃·10H₂O 晶体。", "晶体风化失水，最终得到白色 Na₂CO₃ 粉末。"], "talk": ["变化链条题按「氧化→吸水→吸 CO₂→风化」四步写全，方程式与现象一一对应。"], "title": "案例：钠在空气中久置，最终变成什么"}, "intro": "钠是教材研究物质性质的第一个完整案例：银白色、质软、密度比水小、熔点低，常温被氧气氧化成 Na₂O，加热生成 Na₂O₂。==金属钠保存在煤油中，是因为它既不与煤油反应、密度又比煤油大，能隔绝空气和水。==这一句把钠的大半性质都串起来了。", "learn": [{"h": "物理性质与保存", "p": "**银白色固体、质软（可用小刀切割）、密度比水小（0.97 g/cm³）、熔点低（97.8 ℃）**。\n\n切开钠后切面很快变暗——那是生成了白色的 **Na₂O**。"}, {"h": "与氧气反应：条件不同，产物不同", "p": "常温：4Na + O₂ ＝ 2Na₂O；加热：2Na + O₂ ＝(点燃/加热) Na₂O₂。\n\n==钠与氧气反应的产物由条件决定：常温生成白色 Na₂O，加热生成淡黄色 Na₂O₂。==Na₂O₂ 是**过氧化物**，氧元素为 −1 价，这是它和 Na₂O 最大的区别。"}, {"h": "Na₂O 与 Na₂O₂ 的比较", "p": "两者都能与水反应生成 NaOH：Na₂O + H₂O ＝ 2NaOH；2Na₂O₂ + 2H₂O ＝ 4NaOH + O₂↑。\n\n区别：Na₂O₂ 与水（或 CO₂）反应会**放出氧气**，所以它能做供氧剂；Na₂O 不放氧。颜色也不同：Na₂O 白色，Na₂O₂ 淡黄色。"}, {"h": "易错提醒", "p": "易错提醒：钠与铁对比是为了说明**同为金属、性质有共性也有差异**（铁在常温下不与氧气剧烈反应、硬度大）；比较时抓住「条件—现象—产物」三要素，不要只记结论。"}], "pitfalls": ["Na 与 O₂ 常温/加热产物混淆（颜色也要对应记）。", "Na₂O₂ 中氧的化合价写成 −2。"], "svg": "<rect x='30' y='20' width='120' height='40' rx='6' fill='#fef3c7'/><text x='90' y='45' text-anchor='middle' font-size='13'>钠 + O₂（常温）</text><rect x='210' y='20' width='120' height='40' rx='6' fill='#fff'/><text x='270' y='45' text-anchor='middle' font-size='13'>Na₂O 白色</text><rect x='30' y='85' width='120' height='40' rx='6' fill='#fef3c7'/><text x='90' y='110' text-anchor='middle' font-size='13'>钠 + O₂（加热）</text><rect x='210' y='85' width='120' height='40' rx='6' fill='#fef9c3'/><text x='270' y='110' text-anchor='middle' font-size='13'>Na₂O₂ 淡黄色</text><line x1='150' y1='40' x2='210' y2='40' stroke='#94a3b8'/><line x1='150' y1='105' x2='210' y2='105' stroke='#94a3b8'/>", "svgCap": "条件决定产物：常温 Na₂O（白色），加热 Na₂O₂（淡黄色）。"}, "video": {"bvid": "BV1zK411674L", "p": 1, "t": "研究物质性质的方法和程序（一）", "dur": "20:47", "vtop": ["四种方法：观察、实验、分类、比较。", "基本程序：观察→预测→实验→结论，顺序不能乱。", "钠与氧气：常温 Na₂O（白色），加热 Na₂O₂（淡黄色）。"], "vsum": "方法四件套（观察、实验、分类、比较）加上固定程序（==观察→预测→实验→结论==），是研究任何新物质的通用打法。钠是第一个案例：保存在**煤油**中；常温被氧化成白色 **Na₂O**，加热生成淡黄色 **Na₂O₂**（氧为 −1 价，能与水、CO₂ 反应放氧，可作**供氧剂**）；与铁的比较说明金属有共性、更有个性。\n易错提醒：钠在常温下被氧化成白色 Na₂O、加热时生成淡黄色 Na₂O₂，两种产物的颜色一定要对应记准。", "vtech": ["看到排序题信号 → 默念「观察、预测、实验、结论」，预测永远在实验前。", "看到钠与氧气的题 → 先问条件：常温白色 Na₂O，加热淡黄 Na₂O₂。"], "vgaokao": [], "from": 0}}, "chem_c005": {"name": "氯气的性质", "sec": 2, "secTitle": "研究物质性质的方法和程序", "page": 17, "desc": "黄绿色有毒气体：与金属、氢气、水的反应，HClO 的漂白性与氯水的成分。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c003"], "next": [], "content": {"advance": {"a": "Cl₂ 溶于水生成 HClO，HClO 强氧化性杀灭微生物。氯味来自少量挥发出的 Cl₂/HClO；水中 HClO 浓度被控制在很低水平，且 Cl₂+H₂O 的反应可逆、程度有限，所以刺激性小。", "kind": "self", "q": "自来水厂用氯气消毒的原理是什么？为什么游泳池的水有淡淡的「氯味」却不刺鼻伤人？（从平衡角度简单说明）"}, "apply": [{"ans": 2, "opts": ["干燥的氯气能使有色布条褪色", "新制氯水可长期敞口保存", "氯水漂白的原理是 HClO 的强氧化性", "氯水中只含 Cl₂ 一种溶质粒子"], "q": "下列关于氯水的说法正确的是（ ）", "why": "漂白靠 HClO；干燥 Cl₂ 无漂白性；氯水须避光密封保存；氯水含多种分子和离子。"}], "basics": [{"ans": 1, "opts": ["黄色", "苍白色", "蓝紫色", "红色"], "q": "氢气在氯气中燃烧的火焰颜色是（ ）", "why": "H₂ 在 Cl₂ 中安静燃烧，发出苍白色火焰，生成 HCl。"}, {"ans": 1, "opts": ["FeCl₂", "FeCl₃", "Fe₃O₄", "Fe(OH)₃"], "q": "氯气与铁反应的产物是（ ）", "why": "氯气氧化性强，把铁氧化为 +3 价，生成 FeCl₃。"}], "case": {"a": "先变红后褪色；久置后主要成分为稀盐酸，不再有漂白性。", "hints": ["石蕊遇酸变红，遇 HClO 被漂白，两步分开答。", "久置关键：HClO 见光分解成 HCl 和 O₂。"], "q": "把氯气通入紫色石蕊试液，现象如何？把新制氯水在阳光下久置，最终溶液的成分主要是什么？", "steps": ["通入氯气后生成 HCl 和 HClO：石蕊先因酸性变红。", "随后 HClO 把红色氧化褪去：先变红后褪色。", "久置时 2HClO ＝(光照) 2HCl + O₂↑，漂白成分消失。", "最终溶液主要成分是稀盐酸（HCl），失去漂白性。"], "talk": ["现象题要把「谁起作用」点名：变红靠 H⁺，褪色靠 HClO，分开写才完整。"], "title": "案例：氯水为什么能漂白，久置为什么失效"}, "intro": "氯气是按「观察→预测→实验→结论」程序研究的第二个案例，性质密度大、考点多：与金属、与氢气、与水、漂白性，每条都要连现象一起记。==氯气有毒，实验必须在通风条件下进行，闻气味只能用飘闻法。==", "learn": [{"h": "物理性质", "p": "**黄绿色气体**，有**刺激性气味**，**有毒**，密度比空气大，**能溶于水**（常温下约 1 体积水溶解 2 体积氯气）。实验室制取/收集时常用向上排空气法或排饱和食盐水法。"}, {"h": "与金属和氢气反应", "p": "氯气性质活泼，能与大多数金属反应生成高价氯化物：2Fe + 3Cl₂ ＝(点燃) 2FeCl₃（棕褐色烟）；Cu + Cl₂ ＝(点燃) CuCl₂（棕黄色烟）。\n\n==氯气与铁反应生成 FeCl₃ 而不是 FeCl₂，体现了氯气的强氧化性。==与氢气：H₂ + Cl₂ ＝(点燃) 2HCl，火焰呈**苍白色**，瓶口有白雾。"}, {"h": "与水反应与漂白性", "p": "Cl₂ + H₂O ⇌ HCl + **HClO**（次氯酸）。**次氯酸**有强氧化性，能**杀菌消毒、漂白**。\n\n==真正起漂白作用的是 HClO，不是 Cl₂ 本身；干燥的氯气没有漂白性。==氯水成分复杂（Cl₂、HClO、H₂O、H⁺、Cl⁻ 等），久置后 HClO 见光分解，氯水最终变成稀盐酸而失效。"}, {"h": "易错提醒", "p": "易错提醒：氯水使石蕊试液**先变红后褪色**——先变红是酸性（H⁺），后褪色是 HClO 的漂白；只答褪色会丢一半分。"}], "pitfalls": ["把漂白作用记在 Cl₂ 头上（实为 HClO）。", "Fe 与 Cl₂ 产物写成 FeCl₂。", "石蕊现象只答褪色、漏掉先变红。"], "svg": "<rect x='130' y='12' width='100' height='32' rx='6' fill='#fef9c3'/><text x='180' y='33' text-anchor='middle' font-size='13'>氯气 Cl₂</text><rect x='10' y='80' width='80' height='30' rx='6' fill='#e0f2fe'/><text x='50' y='100' text-anchor='middle' font-size='12'>+金属→盐</text><rect x='105' y='80' width='80' height='30' rx='6' fill='#e0f2fe'/><text x='145' y='100' text-anchor='middle' font-size='12'>+H₂→HCl</text><rect x='200' y='80' width='80' height='30' rx='6' fill='#e0f2fe'/><text x='240' y='100' text-anchor='middle' font-size='12'>+H₂O→HClO</text><rect x='295' y='80' width='70' height='30' rx='6' fill='#fee2e2'/><text x='330' y='100' text-anchor='middle' font-size='12'>有毒!</text><line x1='140' y1='44' x2='60' y2='80' stroke='#94a3b8'/><line x1='170' y1='44' x2='150' y2='80' stroke='#94a3b8'/><line x1='200' y1='44' x2='235' y2='80' stroke='#94a3b8'/><line x1='225' y1='44' x2='320' y2='80' stroke='#94a3b8'/>", "svgCap": "氯气的三条反应线：与金属成盐、与氢气成 HCl、与水生成有漂白性的 HClO。"}, "video": {"bvid": "BV1zK411674L", "p": 2, "t": "研究物质性质的方法和程序（二）", "dur": "21:27", "vtop": ["氯气黄绿色、有毒，闻气味用飘闻法。", "与铁反应生成 FeCl₃，强氧化性。", "漂白靠 HClO；石蕊先变红后褪色。"], "vsum": "氯气：黄绿色、刺激性气味、有毒、能溶于水。与金属生成**高价盐**（Fe→**FeCl₃**，棕褐色烟），与氢气苍白色火焰生成 HCl，与水生成 HCl 和 HClO。漂白、杀菌靠 **HClO**，干燥氯气不漂白；氯水久置变稀盐酸。**新制氯水**==使石蕊先变红后褪色==，是必考现象。\n易错提醒：真正起漂白、杀菌作用的是 HClO 而不是 Cl₂，干燥的氯气本身并不漂白。", "vtech": ["看到「漂白」信号 → 答题落点写 HClO，不写 Cl₂。", "看到石蕊现象 → 分两步写：先变红（酸性）后褪色（漂白）。"], "vgaokao": [], "from": 0}}, "chem_c006": {"name": "物质的量与阿伏加德罗常数", "sec": 3, "secTitle": "化学中常用的物理量——物质的量", "page": 23, "desc": "物质的量是数粒子的批量单位：n ＝ N / N_A，N_A ≈ 6.02×10²³ mol⁻¹。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c007"], "content": {"advance": {"kind": "mcq", "q": "2 mol H₂O 中含氢原子的数目约为（ ）", "opts": ["6.02×10²³", "1.204×10²⁴", "2.408×10²⁴", "4.816×10²⁴"], "ans": 2, "why": "2 mol H₂O 含 4 mol H 原子，4 × 6.02×10²³ ＝ 2.408×10²⁴。"}, "apply": [{"q": "9.03×10²³ 个二氧化碳分子的物质的量是（ ）", "opts": ["1 mol", "1.5 mol", "2 mol", "0.5 mol"], "ans": 1, "why": "n = N / N_A = 9.03×10²³ / 6.02×10²³ ＝ 1.5 mol。"}], "basics": [{"ans": 1, "opts": ["克", "摩尔", "个", "千克"], "q": "物质的量的单位是（ ）", "why": "物质的量是国际单位制基本物理量之一，单位为摩尔（mol）。"}], "case": {"a": "① ④。", "hints": ["先看状态：气体摩尔体积只适用于气体，且要在标准状况。", "再看体积：不是标况就不给体积换算。"], "q": "下列说法正确的是（ ）① 标准状况下，1 mol 任何气体的体积都约为 22.4 L ② 1 mol 水的质量是 18 g/mol ③ 物质的量就是物质的质量 ④ 标准状况下，0.5 mol H₂ 的体积约为 11.2 L", "steps": ["① 对：标况 0 ℃、101 kPa，适用于任何气体（含混合气体）。", "② 错：质量是 18 g，单位 g/mol 是摩尔质量的单位。", "③ 错：物质的量与质量是两个不同的物理量。", "④ 对：0.5 × 22.4 ＝ 11.2 L。（注：气体摩尔体积在下一节系统讲，这里先建立印象。）"], "talk": ["判断题先扫单位和条件：单位错位、缺「标准状况」，八成就是错误项。"], "title": "案例：判断题逐个排雷"}, "intro": "微观粒子数不过来，就找个「批量单位」：像一打鸡蛋是 12 个，**物质的量**就是化学里数粒子的批量单位。==物质的量是表示含有一定数目微观粒子的集合体的物理量，符号 n，单位摩尔（mol）。==", "learn": [{"h": "阿伏加德罗常数", "p": "1 mol 任何粒子所含的粒子数叫做**阿伏加德罗常数**，符号 **N_A**，近似值 **6.02×10²³ mol⁻¹**。\n\n==粒子数 N、物质的量 n、阿伏加德罗常数三者的关系是 n ＝ N / N_A。==注意：说「1 mol」时必须指明粒子种类（1 mol H₂、1 mol H⁺），不能笼统说 1 mol 氢。"}, {"h": "什么叫「粒子」", "p": "这里的粒子指**分子、原子、离子、质子、中子、电子**等微观粒子。宏观物质（1 mol 铁钉、1 mol 面粉）不能用物质的量描述。\n\n易错提醒：「物质的量」是专有名词，四个字不能拆开说成「物质量」，更不能说「摩尔数」。"}], "pitfalls": ["说物质的量时不指明粒子种类。", "把 N_A 的值写成没有单位的纯数字（应有单位 mol⁻¹）。"], "svg": "<rect x='20' y='45' width='90' height='40' rx='6' fill='#e0f2fe'/><text x='65' y='70' text-anchor='middle' font-size='13'>粒子数 N</text><rect x='150' y='45' width='80' height='40' rx='6' fill='#dbeafe'/><text x='190' y='70' text-anchor='middle' font-size='13'>n = N/N_A</text><rect x='270' y='45' width='90' height='40' rx='6' fill='#e0f2fe'/><text x='315' y='70' text-anchor='middle' font-size='13'>物质的量 n</text><line x1='110' y1='65' x2='150' y2='65' stroke='#94a3b8'/><line x1='230' y1='65' x2='270' y2='65' stroke='#94a3b8'/><text x='190' y='115' text-anchor='middle' font-size='12' fill='#64748b'>N_A ≈ 6.02×10²³ mol⁻¹</text>", "svgCap": "数粒子的换算：n = N / N_A，N_A 是每摩尔所含的粒子数。"}, "video": {"bvid": "BV1zK411674L", "p": 3, "t": "化学中常用的物理量——物质的量（一）", "dur": "24:12", "vtop": ["n ＝ N / N_A，N_A ≈ 6.02×10²³ mol⁻¹。", "摩尔质量数值等于相对分子质量，单位 g/mol。", "换算先统一到 n 再出发。"], "vsum": "**物质的量** n 是微观粒子数的批量单位，桥梁是 N_A ≈ 6.02×10²³ mol⁻¹ 与**摩尔质量 M**（数值等于**相对分子质量**、单位 g/mol）。做题总路线：质量除以 M、==个数除以 N_A，先都换成 n==；求复合粒子（分子中的原子、离子所带电荷等）记得乘**化学式下标**。说「1 mol」必须指明粒子种类。\n易错提醒：求分子中的原子、离子所带电荷等复合粒子的数目时，一定要记得乘化学式中的下标。", "vtech": ["看到质量/个数混合换算 → 全部先换成 n（m÷M、N÷N_A）再求目标。", "看到「分子中原子数」 → 分子 mol 先算，再乘下标。"], "vgaokao": [], "from": 0}}, "chem_c007": {"name": "摩尔质量与换算枢纽", "sec": 3, "secTitle": "化学中常用的物理量——物质的量", "page": 25, "desc": "n ＝ m / M；一切换算先统一到 n，复合粒子注意乘下标倍数。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c006"], "next": ["chem_c008", "chem_c009", "chem_c011"], "content": {"advance": {"a": "60 g。两个独立来源的量（微粒总数、总质量）交叉验证后结果一致（n = 1 mol、M = 60 g/mol），互相印证了计算无误。", "kind": "self", "q": "某气体由双原子分子组成。测得 6.02×10²³ 个该气体分子的质量为 60 g。求该气体的摩尔质量，并说说这道题为什么给了你两个数据。"}, "apply": [{"ans": 2, "opts": ["16 g", "8 g", "32 g", "64 g"], "q": "标准状况下，11.2 L 某气体的质量为 16 g，该气体的摩尔质量是（ ）", "why": "标况 11.2 L 为 0.5 mol，M = 16 / 0.5 ＝ 32 g/mol。"}, {"ans": 0, "opts": ["3.01×10²³", "6.02×10²³", "1.204×10²⁴", "1.806×10²⁴"], "q": "质量为 49 g 的 H₂SO₄ 中氧原子的数目约为（ ）", "why": "49 g H₂SO₄ 为 0.5 mol，含氧原子 0.5×4＝2 mol，数目 2×6.02×10²³＝1.204×10²⁴。"}], "basics": [{"ans": 1, "opts": ["16 g", "16 g/mol", "32 g", "32 g/mol"], "q": "氧气的摩尔质量是（ ）", "why": "摩尔质量带单位 g/mol；O₂ 相对分子质量 32，故摩尔质量 32 g/mol。"}, {"ans": 2, "opts": ["36 g", "72 g", "9 g", "18 g"], "q": "2 mol H₂O 的质量是（ ）", "why": "m = nM = 2 × 18 ＝ 36 g。"}], "case": {"a": "2 mol H₂O 含氢原子 2.408×10²⁴ 个（约）。", "hints": ["水分子中氢原子数是水分子的 2 倍，先算分子再乘 2。", "N ＝ n × N_A。"], "q": "2 mol H₂O 中含有多少个氢原子？（用科学计数法，N_A 取 6.02×10²³）", "steps": ["H₂O 分子数：N(H₂O) ＝ 2 mol × 6.02×10²³ mol⁻¹ ＝ 1.204×10²⁴。", "每个 H₂O 分子含 2 个 H 原子：H 原子物质的量 ＝ 2 × 2 mol ＝ 4 mol。", "H 原子数 ＝ 4 × 6.02×10²³ ＝ 2.408×10²⁴。"], "talk": ["复合粒子（分子里的原子）先乘组成倍数：先算分子的 mol，再 ×每分子的原子个数。"], "title": "案例：含几个原子的复合换算"}, "intro": "把粒子数和质量接起来的是**摩尔质量**。==单位物质的量的物质所具有的质量叫做摩尔质量，符号 M，单位 g/mol，数值上等于该粒子的相对原子质量或相对分子质量。==有了它，n、m、N、V 四个量就能互相换算。", "learn": [{"h": "两个核心公式", "p": "质量换算：**n ＝ m / M**；粒子数换算：**n ＝ N / N_A**。\n\n==一切换算都以物质的量 n 为中心：给质量先除以 M，给个数先除以 N_A。==做题时先把已知量统一换成 n，再去求目标量，出错率最低。"}, {"h": "摩尔质量怎么查", "p": "单质看相对原子质量：M(Na) ＝ 23 g/mol，M(Fe) ＝ 56 g/mol；化合物按化学式加总：M(H₂SO₄) ＝ 2×1 + 32 + 4×16 ＝ 98 g/mol；离子近似等于对应原子：M(Na⁺) ＝ 23 g/mol（电子质量忽略）。"}, {"h": "易错提醒", "p": "易错提醒：摩尔质量的数值等于相对分子质量，但**单位不同**（g/mol 对 无单位）；说「1 mol CO₂ 的质量是 44 g/mol」是把 m 和 M 混为一谈，质量 44 g、摩尔质量 44 g/mol。"}], "pitfalls": ["m 与 M 单位混用（g 与 g/mol）。", "复合粒子忘记乘化学式中的下标倍数。"], "svg": "<circle cx='190' cy='65' r='26' fill='#2563eb'/><text x='190' y='71' text-anchor='middle' font-size='15' fill='#fff'>n</text><text x='60' y='30' font-size='13'>m（质量）÷M</text><text x='255' y='30' font-size='13'>N（个数）÷N_A</text><text x='55' y='115' font-size='13'>V（气体，标况）÷22.4</text><text x='250' y='115' font-size='13'>c×V（溶液）</text><line x1='90' y1='38' x2='165' y2='55' stroke='#94a3b8'/><line x1='255' y1='38' x2='215' y2='55' stroke='#94a3b8'/><line x1='120' y1='100' x2='168' y2='78' stroke='#94a3b8'/><line x1='262' y1='100' x2='214' y2='78' stroke='#94a3b8'/>", "svgCap": "换算枢纽图：m、N、V、c 都先换成 n，再由 n 出发求目标。"}, "video": {"bvid": "BV1zK411674L", "p": 3, "t": "化学中常用的物理量——物质的量（一）", "dur": "24:12", "vtop": ["n ＝ N / N_A，N_A ≈ 6.02×10²³ mol⁻¹。", "摩尔质量数值等于相对分子质量，单位 g/mol。", "换算先统一到 n 再出发。"], "vsum": "**物质的量** n 是微观粒子数的批量单位，桥梁是 N_A ≈ 6.02×10²³ mol⁻¹ 与**摩尔质量 M**（数值等于**相对分子质量**、单位 g/mol）。做题总路线：质量除以 M、==个数除以 N_A，先都换成 n==；求复合粒子（分子中的原子、离子所带电荷等）记得乘**化学式下标**。说「1 mol」必须指明粒子种类。\n易错提醒：求分子中的原子、离子所带电荷等复合粒子的数目时，一定要记得乘化学式中的下标。", "vtech": ["看到质量/个数混合换算 → 全部先换成 n（m÷M、N÷N_A）再求目标。", "看到「分子中原子数」 → 分子 mol 先算，再乘下标。"], "vgaokao": [], "from": 0}}, "chem_c008": {"name": "气体摩尔体积与阿伏加德罗定律", "sec": 3, "secTitle": "化学中常用的物理量——物质的量", "page": 28, "desc": "标况 22.4 L/mol 的两个前提；同温同压体积比＝物质的量比，密度比＝摩尔质量比。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c007"], "next": [], "content": {"advance": {"ans": 1, "kind": "mcq", "opts": ["0.2NA", "0.4NA", "0.6NA", "0.8NA"], "q": "标准状况下，4.48 L CO₂ 中含有的氧原子数为（ ）", "why": "4.48 / 22.4 ＝ 0.2 mol CO₂，氧原子 0.4 mol，即 0.4NA。"}, "apply": [{"ans": 2, "opts": ["1 mol", "0.5 mol", "2 mol", "0.25 mol"], "q": "标准状况下，某气体 5.6 L，质量 14 g，则此气体可能是（ ）的摩尔质量为 56 g/mol", "why": "5.6 / 22.4 ＝ 0.25 mol，M ＝ 14 / 0.25 ＝ 56 g/mol。注意题干问法：选项应为物质名，本题以数值表述，作为换算练习。"}, {"q": "标准状况下，5.6 L 某气体的质量为 14 g，该气体的摩尔质量是（ ）", "opts": ["14 g/mol", "28 g/mol", "56 g/mol", "112 g/mol"], "ans": 2, "why": "n = 5.6 / 22.4 ＝ 0.25 mol；M = 14 / 0.25 ＝ 56 g/mol。"}], "basics": [{"ans": 1, "opts": ["0 ℃、101 kPa", "25 ℃、101 kPa", "0 ℃、100 kPa", "273 ℃、101 kPa"], "q": "标准状况是指（ ）", "why": "标准状况：0 ℃（273 K）、101 kPa。"}, {"ans": 2, "opts": ["水", "酒精", "CO₂", "苯"], "q": "标准状况下，下列物质能用 22.4 L/mol 计算体积的是（ ）", "why": "只有气体适用；水、酒精、苯在标况下不是气体。"}], "case": {"a": "体积比（即物质的量比、分子数比）1∶2；质量比 1∶32；密度比 1∶16。", "hints": ["体积比直接等于物质的量比，再连到分子数。", "质量比用 m ＝ nM 同算：注意两边 mol 不同。"], "q": "标准状况下，11.2 L H₂ 与 22.4 L O₂ 相比：物质的量之比、分子数之比、质量之比、密度之比各是多少？", "steps": ["n(H₂) ＝ 11.2/22.4 ＝ 0.5 mol；n(O₂) ＝ 22.4/22.4 ＝ 1 mol，比为 1∶2。", "分子数比 ＝ 物质的量比 ＝ 1∶2。", "质量：H₂ 为 0.5×2 ＝ 1 g；O₂ 为 1×32 ＝ 32 g，比为 1∶32。密度比 ＝ 摩尔质量之比 ＝ 2∶32 ＝ 1∶16。"], "talk": ["同温同压四连比：体积、mol、分子数三比相同；质量、密度比等于 M 之比（注意按各自 mol 核算）。"], "title": "案例：同温同压的连比问题"}, "intro": "同温同压下，气体分子间的距离相同，体积只由分子个数决定。==单位物质的量的气体所占的体积叫做气体摩尔体积，符号 V_m，标准状况下约为 22.4 L/mol。==这句话里每个限定词都是考点。", "learn": [{"h": "成立的两个前提", "p": "气体摩尔体积只适用于**气体**（纯净气体或混合气体都行）；22.4 L/mol 只适用于**标准状况**（0 ℃、101 kPa）。\n\n==看到 22.4 L/mol，先核对：是气体吗？是标准状况吗？两条都满足才能用。==常温常压下 1 mol 气体体积约为 24.5 L，不等于 22.4 L。"}, {"h": "阿伏加德罗定律", "p": "**同温同压下，相同体积的任何气体都含有相同数目的分子**，即 **V₁/V₂ ＝ n₁/n₂ ＝ N₁/N₂**。\n\n由此推出：同温同压下**密度之比 ＝ 摩尔质量之比**（ρ₁/ρ₂ ＝ M₁/M₂），这是求未知气体摩尔质量的常用招。"}, {"h": "易错提醒", "p": "易错提醒：标准状况下水、苯、酒精、四氯化碳都是液体，SO₃ 是固体——给出它们的体积求 mol 是经典陷阱；反过来，给质量求这些物质的体积也不能套用 22.4。"}], "pitfalls": ["非标况套用 22.4 L/mol。", "对液体/固体使用气体摩尔体积。", "密度比误写为体积比。"], "svg": "<rect x='25' y='30' width='150' height='80' rx='8' fill='#f0f9ff'/><circle cx='55' cy='55' r='4' fill='#2563eb'/><circle cx='90' cy='50' r='4' fill='#2563eb'/><circle cx='125' cy='58' r='4' fill='#2563eb'/><circle cx='70' cy='85' r='4' fill='#2563eb'/><circle cx='110' cy='88' r='4' fill='#2563eb'/><text x='100' y='128' text-anchor='middle' font-size='12'>1 mol H₂</text><rect x='215' y='30' width='150' height='80' rx='8' fill='#f0f9ff'/><circle cx='245' cy='55' r='4' fill='#dc2626'/><circle cx='280' cy='50' r='4' fill='#dc2626'/><circle cx='315' cy='58' r='4' fill='#dc2626'/><circle cx='260' cy='85' r='4' fill='#dc2626'/><circle cx='300' cy='88' r='4' fill='#dc2626'/><text x='290' y='128' text-anchor='middle' font-size='12'>1 mol O₂（标况同为 22.4 L）</text>", "svgCap": "阿伏加德罗定律：同温同压、相同体积 → 相同分子数，与气体种类无关。"}, "video": {"bvid": "BV1zK411674L", "p": 4, "t": "化学中常用的物理量——物质的量（二）", "dur": "20:22", "vtop": ["22.4 L/mol 只限标准状况下的气体。", "同温同压：体积比＝物质的量比＝分子数比。", "密度比＝摩尔质量比。"], "vsum": "**气体摩尔体积** V_m：标况下约 **22.4 L/mol**，前提是「气体」加「**标准状况**」，缺一不可（水、苯、SO₃ 在标况都不是气体）。**阿伏加德罗定律**：同温同压下体积比＝物质的量比＝分子数比；==密度比＝摩尔质量比==。常温常压下 1 mol 气体约 24.5 L，不要和 22.4 混。\n易错提醒：22.4 L/mol 只适用于标准状况下的气体，非标况或非气体硬套这个数值是这类题最常见的丢分点。", "vtech": ["看到 22.4 → 先核两件事：气体？标况？有一个不满足就停手。", "看到「同温同压求密度比/求 M」 → 直接写 ρ 比 ＝ M 比。"], "vgaokao": [], "from": 0}}, "chem_c009": {"name": "物质的量浓度", "sec": 3, "secTitle": "化学中常用的物理量——物质的量", "page": 31, "desc": "c ＝ n / V：V 是溶液体积；离子浓度 = 盐浓度 × 下标。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c007"], "next": ["chem_c010"], "content": {"advance": {"kind": "self", "q": "某溶液中同时含 0.1 mol/L 的 MgCl₂ 和 0.1 mol/L 的 NaCl，求 Na⁺ 与 Cl⁻ 的物质的量浓度。", "a": "c(Na⁺) ＝ 0.1 mol/L（只来自 NaCl，1∶1）；c(Cl⁻) ＝ 0.1×2 + 0.1×1 ＝ 0.3 mol/L（MgCl₂ 出 2 份、NaCl 出 1 份，分别算完再相加）。"}, "apply": [{"q": "从 1 L 0.5 mol/L 的 NaCl 溶液中取出 50 mL，取出部分的浓度是（ ）", "opts": ["0.05 mol/L", "0.1 mol/L", "0.5 mol/L", "1 mol/L"], "ans": 2, "why": "溶液均一，取出部分浓度不变，仍为 0.5 mol/L。"}, {"q": "200 mL 0.5 mol/L Na₂SO₄ 溶液中 Na⁺ 的物质的量是（ ）", "opts": ["0.1 mol", "0.2 mol", "0.05 mol", "0.4 mol"], "ans": 1, "why": "Na₂SO₄ 的物质的量 ＝ 0.2 L × 0.5 mol/L ＝ 0.1 mol，Na⁺ 为其 2 倍 ＝ 0.2 mol。"}], "basics": [{"ans": 1, "opts": ["1 mol/L", "0.5 mol/L", "2 mol/L", "0.25 mol/L"], "q": "将 0.5 mol NaCl 溶于水配成 1 L 溶液，浓度为（ ）（假定体积为 1 L）", "why": "c = n/V = 0.5 / 1 ＝ 0.5 mol/L（以选项为准应为 0.5）。"}, {"ans": 0, "opts": ["溶液的体积", "溶剂的体积", "溶质的质量", "溶液的质量"], "q": "物质的量浓度公式中的 V 指的是（ ）", "why": "V 是溶液体积，不是溶剂体积——这是最常见的概念错误。"}], "case": {"a": "Fe³⁺ 的浓度为 0.2 mol/L。", "hints": ["先用电荷/化学式比例：1 个 Fe₂(SO₄)₃ 含 2 个 Fe³⁺。", "浓度比等于化学式中的个数比。"], "q": "0.1 mol/L 的 Fe₂(SO₄)₃ 溶液中，Fe³⁺ 的物质的量浓度是多少？", "steps": ["Fe₂(SO₄)₃ 中 Fe³⁺ 与盐的个数比为 2∶1。", "c(Fe³⁺) ＝ 2 × 0.1 mol/L ＝ 0.2 mol/L。", "同理 SO₄²⁻ 浓度为 3 × 0.1 ＝ 0.3 mol/L。"], "talk": ["离子浓度＝盐浓度×化学式中该离子的下标，与取多少体积无关。"], "title": "案例：离子浓度看下标"}, "intro": "比较溶液的「浓稀」，化学用的是每升溶液里溶质的物质的量。==单位体积溶液中所含溶质 B 的物质的量，叫做溶质 B 的物质的量浓度，符号 c_B，单位 mol/L（或 mol·L⁻¹）。==公式只有一个：c ＝ n / V，难的全在细节里。", "learn": [{"h": "公式的三个细节", "p": "c ＝ **n / V**，其中 n 是溶质的物质的量，V 是**溶液的体积**（不是溶剂体积）。\n\n==浓度与取用体积无关：倒出一半，浓度不变。==这是判断题的高频正确项，也是「取出部分浓度变小」陷阱的破法。"}, {"h": "离子浓度", "p": "强电解质在溶液中完全电离：c（离子）＝ c（盐）× **化学式中该离子的个数**。如 0.1 mol/L Al₂(SO₄)₃ 中 c(Al³⁺) ＝ 0.2 mol/L，c(SO₄²⁻) ＝ 0.3 mol/L。"}, {"h": "易错提醒", "p": "易错提醒：「将 1 mol NaCl 溶于 1 L 水」得到的不是 1 mol/L——溶液体积已不是 1 L；正确说法是「配成 1 L 溶液」。做题先分清给的是溶剂体积还是溶液体积。"}], "pitfalls": ["把溶剂体积当作溶液体积代入公式。", "认为取出部分溶液浓度会变。", "离子浓度漏乘下标。"], "svg": "<rect x='110' y='15' width='160' height='36' rx='6' fill='#2563eb'/><text x='190' y='39' text-anchor='middle' font-size='14' fill='#fff'>c = n / V</text><text x='190' y='75' text-anchor='middle' font-size='12'>n：溶质的物质的量（mol）</text><text x='190' y='97' text-anchor='middle' font-size='12'>V：溶液体积（L），不是溶剂体积</text><text x='190' y='119' text-anchor='middle' font-size='12' fill='#dc2626'>浓度与取出的多少无关</text>", "svgCap": "物质的量浓度：一个公式，三个必须盯紧的细节。"}, "video": {"bvid": "BV1zK411674L", "p": 5, "t": "化学中常用的物理量——物质的量（三）", "dur": "23:37", "vtop": ["c ＝ n / V，V 是溶液体积不是溶剂体积。", "配制八步：计算、称量、溶解、转移、洗涤、定容、摇匀、装瓶。", "误差分析只看 n 和 V 谁变了。"], "vsum": "**物质的量浓度 c ＝ n / V**，==V 指溶液体积；溶液均一==，取出部分浓度不变；**离子浓度乘下标**。配制用**容量瓶**（就近选大、用前查漏、不能溶解和存放），八步里最易丢分的是：冷却后再转移、洗涤 2~3 次并转入、**平视定容**、摇匀后不补水。误差分析回到 c＝n/V：n 变小或 V 变大→偏低，反之偏高。\n易错提醒：公式中的 V 指的是溶液体积而不是溶剂体积，代错了浓度必然算错。", "vtech": ["看到误差分析 → 只问两句：溶质少了吗？水多了还是少了？对照 c＝n/V 定偏高偏低。", "看到「溶于 1 L 水」 → 警惕：那不是溶液体积，不能直接当 V。"], "vgaokao": [], "from": 0}}, "chem_c010": {"name": "一定物质的量浓度溶液的配制与误差分析", "sec": 3, "secTitle": "化学中常用的物理量——物质的量", "page": 32, "desc": "八步配制、容量瓶规矩、误差分析回归 c＝n/V。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c009"], "next": [], "content": {"advance": {"a": "重新配制。溶液已经倒入容量瓶且超过刻度线，无法用吸管「精确」吸走多余液体恢复——吸走的量不可控、且瓶内已混匀，只能倒掉重配。", "kind": "self", "q": "配制时不小心加水超过了容量瓶刻度线，能不能用胶头滴管吸出多余的水补救？为什么？"}, "apply": [{"q": "定容时俯视刻度线（视线高于刻度线往下看），所得溶液浓度（ ）", "opts": ["偏高", "偏低", "无影响", "无法判断"], "ans": 0, "why": "俯视时液面实际未达到刻度线，溶液体积偏小，由 c＝n/V 得浓度偏高。"}, {"q": "称量时药品与砝码位置放反且使用了游码，所得浓度（ ）", "opts": ["偏高", "偏低", "无影响", "先高后低"], "ans": 1, "why": "放反且用游码时实际称得质量 ＝ 砝码质量 − 游码质量，小于所需值，溶质偏少，浓度偏低。"}], "basics": [{"ans": 2, "opts": ["量筒", "烧杯", "容量瓶", "圆底烧瓶"], "q": "配制一定物质的量浓度溶液的核心仪器是（ ）", "why": "容量瓶是唯一带刻度线的精密定容仪器。"}, {"ans": 1, "opts": ["托盘天平", "500 mL 容量瓶", "烧杯", "滴定管"], "q": "配制 480 mL 0.1 mol/L 的溶液，应选用（ ）", "why": "容量瓶规格有 500 mL，没有 480 mL，选最接近的大规格 500 mL。"}], "case": {"a": "需要 NaCl 5.85 g；误差分析：(1) 偏低；(2) 偏低；(3) 偏高。", "hints": ["先算 n ＝ 0.5 L × 0.2 mol/L ＝ 0.1 mol，再 m ＝ nM。", "误差看 c ＝ n/V：n 小或 V 大→偏低。"], "q": "配制 500 mL 0.2 mol/L NaCl 溶液：(1) 需要 NaCl 多少克？(2) 若称量时药品沾有少量水分、转移时烧杯未洗涤、定容时俯视刻度线，三种情况浓度分别偏高还是偏低？", "steps": ["n ＝ 0.5 × 0.2 ＝ 0.1 mol；m ＝ 0.1 × 58.5 ＝ 5.85 g。", "药品含水分：实际 NaCl 偏少，n 偏小→浓度偏低。", "未洗涤烧杯：部分溶质留在烧杯，n 偏小→浓度偏低。", "俯视定容：加水不足，液面低于刻度，V 偏小→浓度偏高。"], "talk": ["误差分析一律回归 c＝n/V：盯住「溶质少了还是水少了」两个方向，别背长串结论。"], "title": "案例：配制 500 mL 0.2 mol/L NaCl 全流程算一遍"}, "intro": "配制一定物质的量浓度的溶液是本章唯一的操作型考点：步骤、仪器、误差，三件套缺一不可。==配制的核心仪器是容量瓶，它只能配制规格对应体积的溶液，不能储存溶液、不能用来溶解固体。==", "learn": [{"h": "八步操作", "p": "**计算→称量→溶解→转移→洗涤→定容→摇匀→装瓶**。\n\n关键动作：溶解在**烧杯**中进行并冷却至室温再转移；转移要用**玻璃棒引流**；洗涤烧杯和玻璃棒 **2～3 次**，洗涤液全部转入容量瓶；定容至液面离刻度线 1～2 cm 时改用**胶头滴管**滴加，平视凹液面最低处与刻度线相切。"}, {"h": "容量瓶的使用规矩", "p": "用前**查漏**；规格按「就近选大」原则（如配 480 mL 选 500 mL）；不能加热、不能溶解固体、不能长期存放溶液。\n\n==定容摇匀后液面下降是正常现象，不许再补加水。==这是最容易被设成「应该补水」陷阱的地方。"}, {"h": "误差分析的方法", "p": "回到公式 **c ＝ n / V** 逐项看：称量沾水、未洗涤、药品变质 → n 偏小 → 偏低；俯视定容、未冷却就定容 → V 偏小或读数偏大方向不同，要分开判。\n\n易错提醒：仰视定容时实际加水过多，V 偏大，浓度偏低；俯视则相反，浓度偏高。（画个眼睛位置图最稳。）"}], "pitfalls": ["转移时未洗涤烧杯导致浓度偏低却答「无影响」。", "定容后液面下降又补加水。", "在容量瓶里直接溶解固体。"], "svg": "<text x='190' y='25' text-anchor='middle' font-size='13'>计算→称量→溶解→转移→洗涤→定容→摇匀→装瓶</text><rect x='40' y='45' width='140' height='30' rx='6' fill='#fee2e2'/><text x='110' y='65' text-anchor='middle' font-size='12'>俯视定容：V 小→偏高</text><rect x='200' y='45' width='140' height='30' rx='6' fill='#e0f2fe'/><text x='270' y='65' text-anchor='middle' font-size='12'>仰视定容：V 大→偏低</text><rect x='40' y='90' width='140' height='30' rx='6' fill='#e0f2fe'/><text x='110' y='110' text-anchor='middle' font-size='12'>未洗涤：n 小→偏低</text><rect x='200' y='90' width='140' height='30' rx='6' fill='#fee2e2'/><text x='270' y='110' text-anchor='middle' font-size='12'>溶质洒出：n 小→偏低</text>", "svgCap": "误差分析总表：一切回归 c＝n/V，看 n 与 V 谁变了。"}, "video": {"bvid": "BV1zK411674L", "p": 5, "t": "化学中常用的物理量——物质的量（三）", "dur": "23:37", "vtop": ["c ＝ n / V，V 是溶液体积不是溶剂体积。", "配制八步：计算、称量、溶解、转移、洗涤、定容、摇匀、装瓶。", "误差分析只看 n 和 V 谁变了。"], "vsum": "**物质的量浓度 c ＝ n / V**，==V 指溶液体积；溶液均一==，取出部分浓度不变；**离子浓度乘下标**。配制用**容量瓶**（就近选大、用前查漏、不能溶解和存放），八步里最易丢分的是：冷却后再转移、洗涤 2~3 次并转入、**平视定容**、摇匀后不补水。误差分析回到 c＝n/V：n 变小或 V 变大→偏低，反之偏高。\n易错提醒：公式中的 V 指的是溶液体积而不是溶剂体积，代错了浓度必然算错。", "vtech": ["看到误差分析 → 只问两句：溶质少了吗？水多了还是少了？对照 c＝n/V 定偏高偏低。", "看到「溶于 1 L 水」 → 警惕：那不是溶液体积，不能直接当 V。"], "vgaokao": [], "from": 0}}, "chem_c011": {"name": "膨松剂与碳酸氢钠", "sec": 0, "secTitle": "微项目：探秘膨松剂", "page": 34, "desc": "NaHCO₃ 受热分解、遇酸都放 CO₂；用本章方法程序做一次完整探究。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c003", "chem_c007"], "next": [], "content": {"advance": {"a": "取少量样品加热，产生能使澄清石灰水变浑浊的气体，说明含碳酸盐/碳酸氢盐类膨松成分（CO₂ 来自 NaHCO₃ 受热分解：2NaHCO₃ ＝(加热) Na₂CO₃ + H₂O + CO₂↑）。", "kind": "self", "q": "设计一个简单实验，检验某膨松剂的主要成分中含有 NaHCO₃（提示：从受热分解产生 CO₂ 入手）。"}, "apply": [{"ans": 1, "opts": ["促进面团发酵", "受热分解产生 CO₂ 使食品疏松多孔", "防腐保鲜", "增加甜味"], "q": "碳酸氢钠作膨松剂的作用原理是（ ）", "why": "NaHCO₃ 受热分解放出 CO₂ 气体，气体膨胀使食品内部形成空洞。"}], "basics": [{"ans": 1, "opts": ["NaCl", "NaHCO₃", "Na₂CO₃", "CaCO₃"], "q": "家庭蒸馒头常用的膨松剂主要成分是（ ）", "why": "小苏打即碳酸氢钠 NaHCO₃。"}], "case": {"a": "生成 CO₂ 共 0.1 mol，质量 4.4 g；相当于标况下约 2.24 L 气体。", "hints": ["化学计量数比：2 个 NaHCO₃ 出 1 个 CO₂。", "先 n(NaHCO₃) ＝ 16.8/84 ＝ 0.2 mol。"], "q": "16.8 g NaHCO₃ 固体受热完全分解，能生成多少摩尔 CO₂？质量是多少？标准状况下体积约多少？", "steps": ["n(NaHCO₃) ＝ 16.8 g / 84 g·mol⁻¹ ＝ 0.2 mol。", "由 2NaHCO₃ ＝ Na₂CO₃ + H₂O + CO₂↑，n(CO₂) ＝ 0.2 / 2 ＝ 0.1 mol。", "m(CO₂) ＝ 0.1 × 44 ＝ 4.4 g；V ＝ 0.1 × 22.4 ＝ 2.24 L。"], "talk": ["按方程式计量数比例换算：先把已知物换成 mol，再乘系数比，最后换成目标单位。"], "title": "案例：膨松剂里藏着多少气体"}, "intro": "微项目把本章三个工具一次用齐：**碳酸氢钠（小苏打）**受热分解放出 CO₂，面团里就鼓起无数小孔。==膨松剂、胃药、灭火器里都有 NaHCO₃ 的身影，核心都是它「遇热、遇酸放出 CO₂」的性质。==", "learn": [{"h": "NaHCO₃ 的两条反应线", "p": "受热分解：2NaHCO₃ ＝(加热) Na₂CO₃ + H₂O + CO₂↑；与酸反应：NaHCO₃ + HCl ＝ NaCl + H₂O + CO₂↑。\n\n胃酸过多时用它中和胃酸，就是第二条反应线在起作用。"}, {"h": "探究的程序", "p": "微项目的程序和第 2 节一脉相承：提出问题（膨松剂为什么能膨松）→预测（可能受热产生气体）→实验验证（加热、与酸混合观察气泡，用澄清石灰水检验 CO₂）→得出结论。\n\n==本章的方法主线在这里收尾：观察、预测、实验、结论，配制与计算提供定量支撑。=="}, {"h": "易错提醒", "p": "易错提醒：NaHCO₃ 是**碳酸氢钠**（小苏打），Na₂CO₃ 是**碳酸钠**（纯碱、苏打），一字之差别写混；NaHCO₃ 与酸反应是 1∶1 出 1 个 CO₂，受热分解是 2∶1，比例不同不可混用。"}], "pitfalls": ["碳酸钠与碳酸氢钠俗名、化学式混淆。", "受热分解的计量比例（2∶1）写成 1∶1。"], "svg": "<rect x='20' y='50' width='110' height='36' rx='6' fill='#fef3c7'/><text x='75' y='73' text-anchor='middle' font-size='12'>NaHCO₃（小苏打）</text><rect x='170' y='20' width='180' height='30' rx='6' fill='#e0f2fe'/><text x='260' y='40' text-anchor='middle' font-size='12'>加热 → CO₂↑（膨松）</text><rect x='170' y='85' width='180' height='30' rx='6' fill='#e0f2fe'/><text x='260' y='105' text-anchor='middle' font-size='12'>遇酸 → CO₂↑（中和胃酸）</text><line x1='130' y1='60' x2='170' y2='38' stroke='#94a3b8'/><line x1='130' y1='76' x2='170' y2='98' stroke='#94a3b8'/>", "svgCap": "NaHCO₃ 的两条反应线：受热分解与遇酸反应，都放出 CO₂。"}, "video": {"bvid": "BV1zK411674L", "p": 6, "t": "微项目：探秘膨松剂", "dur": "21:02", "vtop": ["NaHCO₃ 受热、遇酸都放出 CO₂。", "受热分解计量比 2∶1，遇酸 1∶1。", "探究程序与第 2 节的四步完全一致。"], "vsum": "微项目用 **NaHCO₃** 收官全章：受热分解 2NaHCO₃ ＝ Na₂CO₃ + H₂O + CO₂↑（膨松），遇酸 NaHCO₃ + HCl ＝ NaCl + H₂O + CO₂↑（中和胃酸）。探究流程正是第 2 节的四步程序，计算正是第 3 节的**计量换算**——==方法与定量在本课合流==。注意**碳酸钠（苏打）**与**碳酸氢钠（小苏打）**不要写混。\n易错提醒：碳酸钠是苏打、碳酸氢钠是小苏打，两者的俗名和化学式千万不要写混。", "vtech": ["看到方程式计算 → 先把已知量换成 mol，按计量数比例推目标物，再换单位。", "看到俗名（小苏打/苏打） → 先翻译成化学式再动笔。"], "vgaokao": [], "from": 0}}, "chem_c012": {"name": "元素与物质的关系", "sec": 1, "secTitle": "元素与物质分类", "page": 44, "desc": "元素是质子数相同的一类原子的总称；同一元素可组成不同单质、不同物质。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c013"], "content": {"advance": {"a": "物质种类繁多但元素只有一百多种，先确定组成元素才能预测性质与分类。地壳中含量最多的是氧、硅、铝、铁：氧组成水与氧化物，硅是半导体材料的主角，铝、铁是常见金属单质与盐的来源。", "kind": "self", "q": "为什么说「元素观」是研究物质的起点？结合地壳中元素含量最多的前几种元素各举一例说明。"}, "apply": [{"ans": 2, "opts": ["水由氢原子和氧原子组成", "氧气由氧元素组成，氧元素由氧分子构成", "二氧化碳由碳元素和氧元素组成", "物质由元素构成"], "q": "下列说法正确的是（ ）", "why": "宏观组成用元素：CO₂ 由碳、氧两种元素组成。A 应说水由氢氧元素组成或水分子由原子构成；B 中元素不由分子构成；D 物质由元素组成、由粒子构成。"}], "basics": [{"ans": 1, "opts": ["中子数", "质子数", "电子数", "质量数"], "q": "决定元素种类的是原子的（ ）", "why": "元素是质子数相同的一类原子的总称，质子数决定元素种类。"}, {"ans": 1, "opts": ["¹²C 与 ¹⁴C", "金刚石与石墨", "水与过氧化氢", "一氧化碳与二氧化碳"], "q": "下列各组物质互为同素异形体的是（ ）", "why": "同素异形体是同种元素组成的不同单质；A 是同位素，C、D 是不同化合物。"}], "case": {"a": "不是同一种物质，二者互为同素异形体；金刚石转化为石墨是化学变化。", "hints": ["先看结构：两者碳原子排列方式不同。", "物理性质差异很大说明是不同物质。"], "q": "金刚石和石墨都由碳元素组成，它们是同一种物质吗？把金刚石转化为石墨是物理变化还是化学变化？", "steps": ["两者组成元素相同，但原子排列方式不同，物理性质差异显著（硬度、导电性），是两种不同的单质。", "它们互为同素异形体。", "转化过程中生成了新物质，属于化学变化。", "燃烧时两者都生成 CO₂，说明化学性质相似。"], "talk": ["判断同素异形体抓两点：同种元素、不同单质；与同位素（原子层面）严格区分。"], "title": "案例：金刚石和石墨是同一种物质吗"}, "intro": "世界上物质成千上万，但组成它们的元素只有一百多种。==元素是质子数（即核电荷数）相同的一类原子的总称。==这一句定义是第 2 章的地基：分类、电离、氧化还原，全都建立在「元素」这个视角上。", "learn": [{"h": "元素的定义：只看质子数", "p": "**元素**是**质子数**相同的一类**原子**的总称。判断是不是同种元素，只看质子数，与中子数、电子数无关。\n\n==元素只论种类、不论个数：说「水由氢元素和氧元素组成」，不能说「由两个氢元素组成」。==描述分子构成时才论个数，如一个水分子由 2 个氢原子和 1 个氧原子构成。"}, {"h": "游离态与化合态", "p": "元素在物质中有两种存在形态：以**单质**形式存在的叫**游离态**，以**化合物**形式存在的叫**化合态**。\n\n如氧气中的氧是游离态，水、二氧化碳中的氧是化合态。同一元素既可以游离态存在，也可以化合态存在。"}, {"h": "同种元素可组成不同物质", "p": "由同种元素组成的**不同单质**互称**同素异形体**，如金刚石与石墨、氧气（O₂）与臭氧（O₃）、红磷与白磷。\n\n==同素异形体是不同物质，物理性质不同，化学性质相似；它们之间的转化是化学变化。==注意：同位素是同种元素的不同原子，不是一回事。"}, {"h": "易错提醒", "p": "易错提醒：物质由**元素**组成、由**分子或原子**构成，两套说法不能混搭；「氧化铁由铁元素和氧原子组成」是典型错误表述。"}], "pitfalls": ["元素只论种类不论个数，描述组成时带数字是高频错误。", "同素异形体与同位素混淆：前者是单质，后者是原子。", "把游离态误解为单质以外的形态。"], "svg": "<rect x='130' y='12' width='100' height='30' rx='6' fill='#2563eb'/><text x='180' y='32' text-anchor='middle' font-size='13' fill='#fff'>元素</text><rect x='30' y='80' width='110' height='30' rx='6' fill='#e0f2fe'/><text x='85' y='100' text-anchor='middle' font-size='12'>游离态：单质</text><rect x='220' y='80' width='110' height='30' rx='6' fill='#e0f2fe'/><text x='275' y='100' text-anchor='middle' font-size='12'>化合态：化合物</text><line x1='155' y1='42' x2='90' y2='80' stroke='#94a3b8'/><line x1='205' y1='42' x2='270' y2='80' stroke='#94a3b8'/>", "svgCap": "元素的两种存在形态：游离态（单质）与化合态（化合物）。"}, "video": {"bvid": "BV1zK411674L", "p": 8, "t": "元素与物质分类(1)", "dur": "20:27", "from": 0, "vtop": ["元素是质子数（核电荷数）相同的一类原子的总称，只论种类不论个数。", "同一元素可以组成不同单质（同素异形体），也可以进入多种化合物。", "分类先看组成：单质只含一种元素，化合物含两种或两种以上元素。"], "vsum": "本课先立元素观：**元素**是质子数相同的一类原子的总称，物质由元素组成，元素在物质中以游离态（单质）或化合态（化合物）存在；金刚石与石墨、氧气与臭氧是**同素异形体**。再学两种分类法：**树状分类**把物质层层分成纯净物与混合物、单质与化合物、氧化物酸碱盐；**交叉分类**从多个角度给同一物质贴标签，如 Na₂CO₃ 既是盐、又是钠盐、又是碳酸盐。判分类题先抓定义边界：==氧化物只含两种元素且一种是氧==，酸电离出的阳离子全是 H⁺，碱电离出的阴离子全是 OH⁻。\n易错提醒：元素只论种类、不论个数，描述物质组成时给元素带上数字是最常见的错误。", "vtech": ["看到分类判断题 → 先写定义再对号：氧化物数元素种类（两种、含氧），酸碱盐看电离出的离子。", "看到「某物质属于哪几类」 → 用交叉分类多角度贴标签，别只答一个类别。"], "vgaokao": []}}, "chem_c013": {"name": "物质的分类方法", "sec": 1, "secTitle": "元素与物质分类", "page": 46, "desc": "树状分类与交叉分类：单质、氧化物、酸、碱、盐的判据与常见陷阱。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c012"], "next": ["chem_c014"], "content": {"advance": {"a": "碱的判据是电离出的阴离子全部是 OH⁻。Na₂CO₃ 电离出 Na⁺ 和 CO₃²⁻，阴离子不是 OH⁻，所以它是盐；只是其水溶液因 CO₃²⁻ 水解呈碱性，俗名才叫纯碱。", "kind": "self", "q": "为什么 Na₂CO₃ 俗称「纯碱」却不是碱？从电离判据说明。"}, "apply": [{"ans": 1, "opts": ["酸", "酸式盐", "碱式盐", "氧化物"], "q": "NaHSO₄、NaHCO₃ 在分类上共同属于（ ）", "why": "两者都由金属阳离子、H 与酸根组成，是酸式盐；电离出的阳离子不全是 H⁺，所以不是酸。"}, {"ans": 0, "opts": ["H₂O、CO₂ 都是氧化物", "NaOH、NH₃·H₂O 都是盐", "Cu、Hg 都是化合物", "空气、海水都是纯净物"], "q": "下列分类正确的一组是（ ）", "why": "H₂O 与 CO₂ 均由两种元素组成且含氧，是氧化物。B 中两者是碱；C 中是单质；D 中是混合物。"}], "basics": [{"ans": 2, "opts": ["KClO₃", "H₂SO₄", "MnO₂", "NaOH"], "q": "下列物质属于氧化物的是（ ）", "why": "氧化物只含两种元素且含氧：MnO₂ 符合；KClO₃、H₂SO₄ 含三种元素，NaOH 是碱。"}, {"ans": 2, "opts": ["酸", "纯净物", "混合物", "化合物"], "q": "盐酸属于（ ）", "why": "盐酸是 HCl 的水溶液，是混合物；纯净物 HCl 气体溶于水前才称氯化氢。"}], "case": {"a": "Na₂CO₃ 是盐、钠盐、碳酸盐（可溶性盐）；预测：能与盐酸反应生成 CO₂。", "hints": ["角度一：看阳离子；角度二：看酸根；角度三：看它是不是纯净物中的哪一大类。"], "q": "用交叉分类法，从三个不同角度说明 Na₂CO₃ 属于哪些类别，并预测它的一条化学性质。", "steps": ["按组成：Na₂CO₃ 是纯净物、化合物、盐。", "按阳离子：属于钠盐；按酸根：属于碳酸盐。", "碳酸盐的通性：能与盐酸反应放出 CO₂，可据此预测并检验。"], "talk": ["交叉分类题要答出多个角度，每个角度都要点名分类标准，只写结论不写标准要扣分。"], "title": "案例：给 Na₂CO₃ 贴满标签"}, "intro": "给物质分类不是贴标签玩，而是为了借已知推未知。教材给出两种方法：**树状分类法**和**交叉分类法**。==分类的标准不同，同一物质可以属于不同的类别。==考试最爱在定义边界上设陷阱。", "learn": [{"h": "树状分类：层层往下分", "p": "物质先分**纯净物**与**混合物**；纯净物再分**单质**与**化合物**；化合物再分**氧化物、酸、碱、盐**等。\n\n==树状分类像家谱：每一层只用一个标准，同一层的类别互相不重叠。==盐酸是混合物（氯化氢的水溶液），不能归入酸类纯净物，这是常见坑。"}, {"h": "四类化合物的判据", "p": "**氧化物**：由两种元素组成、其中一种是氧元素的化合物；**酸**：电离时生成的阳离子全部是 **H⁺** 的化合物；**碱**：电离时生成的阴离子全部是 **OH⁻** 的化合物；**盐**：由金属阳离子（或 NH₄⁺）和酸根阴离子组成的化合物。\n\n判据要逐字抠：「全部」二字决定了 NaHCO₃ 是盐不是酸（它电离出的阳离子还有 Na⁺）。"}, {"h": "交叉分类：一物多标签", "p": "**交叉分类法**从不同角度对同一物质分类。如 Na₂CO₃ 按阳离子是**钠盐**，按酸根是**碳酸盐**，按溶解性是**可溶性盐**。\n\n==交叉分类的价值在于信息更全：知道它是碳酸盐，就能预测它能与酸反应放出 CO₂。==这与下一节用类别预测性质直接衔接。"}, {"h": "易错提醒", "p": "易错提醒：含氧元素的不一定是氧化物（如 KClO₃ 含三种元素，是盐）；含氢元素的不一定是酸（如 NH₃、CH₄）；碱性氧化物、酸性氧化物的判断留到后续章节，先把四类基本判据守住。"}], "pitfalls": ["氧化物只数两种元素：含氧的盐、酸不是氧化物。", "盐酸、氯水等溶液是混合物，不能套纯净物的类别。", "酸式盐不是酸：阳离子不全是 H⁺。"], "svg": "<rect x='140' y='8' width='80' height='26' rx='6' fill='#2563eb'/><text x='180' y='25' text-anchor='middle' font-size='12' fill='#fff'>纯净物</text><rect x='40' y='55' width='80' height='26' rx='6' fill='#e0f2fe'/><text x='80' y='72' text-anchor='middle' font-size='12'>单质</text><rect x='240' y='55' width='80' height='26' rx='6' fill='#e0f2fe'/><text x='280' y='72' text-anchor='middle' font-size='12'>化合物</text><rect x='160' y='102' width='60' height='24' rx='6' fill='#fef3c7'/><text x='190' y='118' text-anchor='middle' font-size='11'>氧化物</text><rect x='228' y='102' width='36' height='24' rx='6' fill='#fef3c7'/><text x='246' y='118' text-anchor='middle' font-size='11'>酸</text><rect x='272' y='102' width='36' height='24' rx='6' fill='#fef3c7'/><text x='290' y='118' text-anchor='middle' font-size='11'>碱</text><rect x='316' y='102' width='36' height='24' rx='6' fill='#fef3c7'/><text x='334' y='118' text-anchor='middle' font-size='11'>盐</text><line x1='160' y1='34' x2='85' y2='55' stroke='#94a3b8'/><line x1='200' y1='34' x2='275' y2='55' stroke='#94a3b8'/><line x1='280' y1='81' x2='240' y2='102' stroke='#94a3b8'/>", "svgCap": "树状分类法：纯净物向下分为单质与化合物，化合物再分氧化物、酸、碱、盐。"}, "video": {"bvid": "BV1zK411674L", "p": 8, "t": "元素与物质分类(1)", "dur": "20:27", "from": 0, "vtop": ["元素是质子数（核电荷数）相同的一类原子的总称，只论种类不论个数。", "同一元素可以组成不同单质（同素异形体），也可以进入多种化合物。", "分类先看组成：单质只含一种元素，化合物含两种或两种以上元素。"], "vsum": "本课先立元素观：**元素**是质子数相同的一类原子的总称，物质由元素组成，元素在物质中以游离态（单质）或化合态（化合物）存在；金刚石与石墨、氧气与臭氧是**同素异形体**。再学两种分类法：**树状分类**把物质层层分成纯净物与混合物、单质与化合物、氧化物酸碱盐；**交叉分类**从多个角度给同一物质贴标签，如 Na₂CO₃ 既是盐、又是钠盐、又是碳酸盐。判分类题先抓定义边界：==氧化物只含两种元素且一种是氧==，酸电离出的阳离子全是 H⁺，碱电离出的阴离子全是 OH⁻。\n易错提醒：元素只论种类、不论个数，描述物质组成时给元素带上数字是最常见的错误。", "vtech": ["看到分类判断题 → 先写定义再对号：氧化物数元素种类（两种、含氧），酸碱盐看电离出的离子。", "看到「某物质属于哪几类」 → 用交叉分类多角度贴标签，别只答一个类别。"], "vgaokao": []}}, "chem_c014": {"name": "分散系：溶液、胶体与浊液", "sec": 1, "secTitle": "元素与物质分类", "page": 49, "desc": "按分散质粒子大小分三类：小于 1 nm 溶液、1~100 nm 胶体、大于 100 nm 浊液。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c013"], "next": ["chem_c015"], "content": {"advance": {"a": "胶体粒子比溶液粒子大得多，但比浊液粒子小得多，且不停地做布朗运动、表面吸附相同电荷互相排斥，所以能较长时间不沉降；一旦破坏电荷平衡就会聚沉。", "kind": "self", "q": "为什么胶体介于溶液与浊液之间却能保持较稳定？从粒子大小与布朗运动角度简单说明。"}, "apply": [{"ans": 1, "opts": ["Fe(OH)₃ 胶体粒子", "Na⁺ 与 Cl⁻", "水分子以外的全部粒子", "什么都检不出"], "q": "把 Fe(OH)₃ 胶体与 NaCl 溶液混合后装入半透膜袋渗析，袋外水中能检出的主要是（ ）", "why": "离子能透过半透膜，胶体粒子不能；渗析正是利用这一点提纯胶体。"}], "basics": [{"ans": 1, "opts": ["能发生丁达尔效应", "分散质粒子直径在 1~100 nm 之间", "外观透明", "能透过滤纸"], "q": "胶体区别于溶液的本质特征是（ ）", "why": "本质区别是粒子大小；丁达尔效应、透过滤纸都是由此派生的性质。"}, {"ans": 2, "opts": ["食盐水", "泥水", "豆浆", "石灰水"], "q": "下列属于胶体的是（ ）", "why": "豆浆中蛋白质等粒子直径在 1~100 nm，是胶体；泥水是浊液，其余是溶液。"}], "case": {"a": "豆浆是胶体、泥水是浊液、食盐水是溶液；用丁达尔效应可区分豆浆与食盐水。", "hints": ["先按稳定性与粒子大小归类。", "区分胶体与溶液想光学性质。"], "q": "豆浆、泥水、食盐水分别属于哪类分散系？用什么简单方法可以把豆浆与食盐水区分开？", "steps": ["食盐水均一稳定，是溶液；豆浆较稳定但粒子较大，是胶体；泥水静置沉降，是悬浊液。", "用一束光照射：豆浆出现光亮通路（丁达尔效应），食盐水没有。", "也可用半透膜：食盐能透过，豆浆中的胶体粒子不能。"], "talk": ["分散系题先归类再选方法：鉴别用丁达尔，分离胶体与溶液用渗析（半透膜）。"], "title": "案例：豆浆、泥水、盐水怎么分"}, "intro": "把泥沙、牛奶、盐水放在一起看，差别不在成分而在「分散得有多细」。==分散系的分类标准只有一个：分散质粒子的直径大小。==记住 1 nm 与 100 nm 两条界线，这一节就通了。", "learn": [{"h": "分散系的组成", "p": "**分散系**是把一种（或多种）物质分散在另一种物质中形成的混合物：被分散的是**分散质**，容纳它的是**分散剂**。\n\n按分散质粒子直径分三类：**溶液**小于 1 nm，**胶体** 1~100 nm，**浊液**大于 100 nm。"}, {"h": "三类分散系对照", "p": "溶液：**均一、稳定**，能透过滤纸和半透膜，如食盐水；胶体：较均一、较稳定，能透过滤纸、**不能透过半透膜**，如 Fe(OH)₃ 胶体、豆浆；浊液：不均一、不稳定，静置分层或沉降，如泥水、油水混合物。\n\n==鉴别与分离都建立在这张对照表上：粒子大小决定能不能透膜、稳不稳定。=="}, {"h": "胶体的常见成员", "p": "生活中胶体很多：豆浆、牛奶、血液、墨水、肥皂水、雾与烟尘（气溶胶）。淀粉溶液、蛋白质溶液也属于胶体。\n\n易错提醒：胶体是**混合物**，不是纯净物；「胶体粒子」可以是多个分子的集合体，不等于单个分子。"}, {"h": "易错提醒", "p": "易错提醒：判断分散系类别看的是分散质粒子直径，不是外观是否透明——有些胶体也透明，有些浊液静置前看起来也均匀。"}], "pitfalls": ["把丁达尔效应说成本质区别（本质是粒子大小）。", "误以为胶体是纯净物或单个大分子必然是胶体粒子。"], "svg": "<rect x='15' y='40' width='105' height='55' rx='6' fill='#e0f2fe'/><text x='67' y='62' text-anchor='middle' font-size='12'>溶液</text><text x='67' y='82' text-anchor='middle' font-size='11' fill='#64748b'>小于 1 nm</text><rect x='135' y='40' width='105' height='55' rx='6' fill='#dbeafe'/><text x='187' y='62' text-anchor='middle' font-size='12'>胶体</text><text x='187' y='82' text-anchor='middle' font-size='11' fill='#64748b'>1~100 nm</text><rect x='255' y='40' width='105' height='55' rx='6' fill='#fef3c7'/><text x='307' y='62' text-anchor='middle' font-size='12'>浊液</text><text x='307' y='82' text-anchor='middle' font-size='11' fill='#64748b'>大于 100 nm</text><text x='187' y='25' text-anchor='middle' font-size='12' fill='#dc2626'>粒子越来越大，稳定性越来越差</text>", "svgCap": "三类分散系按分散质粒子直径划分：溶液、胶体、浊液。"}, "video": {"bvid": "BV1zK411674L", "p": 10, "t": "元素与物质分类(3)", "dur": "20:02", "from": 0, "vtop": ["分散系分类只看分散质粒子大小：小于 1 nm、1~100 nm、大于 100 nm。", "丁达尔效应是胶体的光学性质，是鉴别胶体与溶液最常用的方法。", "Fe(OH)₃ 胶体制备要煮沸、不能搅拌、不能加热过度。"], "vsum": "分散系是被分散的物质（**分散质**）分散在另一种物质（**分散剂**）中形成的混合物。按分散质粒子直径分：溶液小于 1 nm（均一稳定、能透过滤纸和**半透膜**），胶体 1~100 nm（较稳定、能透过滤纸不能透过半透膜），浊液大于 100 nm（不稳定、静置分层或沉降）。==胶体的招牌性质是丁达尔效应==；Fe(OH)₃ 胶体由饱和 FeCl₃ 溶液滴入沸水制得，能吸附悬浮物净水，加电解质、加热或加带相反电荷的胶体都会**聚沉**。\n易错提醒：区分溶液、胶体与浊液的本质是分散质粒子直径的大小，丁达尔效应只是胶体的性质而不是本质区别。", "vtech": ["看到鉴别胶体与溶液 → 首选丁达尔效应：一束光侧面看，胶体有光亮通路。", "看到粒子大小比较题 → 先把单位统一到 nm，再按 1 与 100 两个界限归类。"], "vgaokao": []}}, "chem_c015": {"name": "胶体的性质与丁达尔效应", "sec": 1, "secTitle": "元素与物质分类", "page": 50, "desc": "丁达尔效应鉴别胶体；Fe(OH)₃ 胶体的制备、聚沉与净水应用。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c014"], "next": ["chem_c023"], "content": {"advance": {"a": "明矾中 Al³⁺ 水解生成 Al(OH)₃ 胶体，胶体粒子表面积大、吸附水中悬浮杂质，一起聚沉到水底，从而净水；本质是胶体的吸附与聚沉。", "kind": "self", "q": "明矾净水利用的是什么原理？写出相关的离子反应思路（只需定性说明）。"}, "apply": [{"ans": 3, "opts": ["卤水点豆腐", "长江入海口形成三角洲", "用明矾净水", "阳光穿过树林形成光柱"], "q": "下列现象与胶体聚沉无关的是（ ）", "why": "光柱是丁达尔效应；前三项都是电解质或异性胶体使胶体聚沉的应用。"}], "basics": [{"ans": 1, "opts": ["加电解质", "丁达尔效应", "过滤", "加热"], "q": "鉴别胶体和溶液最简便的方法是（ ）", "why": "丁达尔效应是胶体的光学特征，操作简便且现象明显。"}, {"ans": 1, "opts": ["把 FeCl₃ 溶液滴入冷水", "把饱和 FeCl₃ 溶液滴入沸水并煮沸至红褐色", "把 NaOH 溶液滴入 FeCl₃ 溶液", "把 Fe(OH)₃ 沉淀加水搅拌"], "q": "制备 Fe(OH)₃ 胶体的正确操作是（ ）", "why": "FeCl₃ 在沸水中水解生成 Fe(OH)₃ 胶体；C 得到的是沉淀。"}], "case": {"a": "搅拌使胶体聚沉；应向沸水中滴加饱和 FeCl₃ 溶液，煮沸至红褐色即停，不搅拌。", "hints": ["搅拌与加热过度都会破坏胶体的稳定性。", "正确要点：沸水、饱和 FeCl₃、煮沸至红褐色即停。"], "q": "某同学制备 Fe(OH)₃ 胶体时不断用玻璃棒搅拌，最后得到红褐色沉淀而不是胶体。用胶体性质解释原因，并写出正确的制备要点。", "steps": ["胶体粒子因吸附电荷保持稳定，剧烈搅拌和持续加热会使粒子碰撞聚集而聚沉。", "该同学的操作使 Fe(OH)₃ 粒子聚集成大颗粒沉淀。", "正确做法：向沸水中滴加饱和 FeCl₃ 溶液，继续煮沸至红褐色立即停止加热，全程不搅拌。"], "talk": ["实验题答操作要点要成套：水（蒸馏水煮沸）、试剂（饱和 FeCl₃）、火候（红褐色即停）、禁忌（不搅拌）。"], "title": "案例：制胶体时把液体搅了几下，结果会怎样"}, "intro": "胶体最出名的招牌是丁达尔效应：光束穿过胶体时出现一条光亮的通路。==丁达尔效应是鉴别胶体与溶液最简便的方法。==本节还要拿下 Fe(OH)₃ 胶体的制备，它是实验题的常客。", "learn": [{"h": "丁达尔效应", "p": "当光束通过**胶体**时，在与光束垂直的方向能看到一条光亮的通路，这叫**丁达尔效应**，成因是胶体粒子对光的**散射**。\n\n溶液粒子太小、散射太弱，看不到通路；浊液主要发生反射，也不形成这种通路。清晨林间的光柱、放映机的光束都是生活中的丁达尔效应。"}, {"h": "Fe(OH)₃ 胶体的制备", "p": "向**沸水**中逐滴加入饱和 **FeCl₃** 溶液，继续煮沸至液体呈**红褐色**即停：FeCl₃ + 3H₂O ＝(煮沸) Fe(OH)₃（胶体）+ 3HCl。\n\n==制备三忌：不能用自来水（电解质使胶体聚沉）、不能过度加热（聚沉）、不能搅拌（聚沉成沉淀）。==方程式中 Fe(OH)₃ 后要标注「胶体」，不能写沉淀符号 ↓。"}, {"h": "聚沉与净水", "p": "胶体粒子吸附电荷而稳定；加入**电解质**、加热、或加入带相反电荷的胶体，都能使胶体**聚沉**。\n\n应用：明矾溶于水生成 Al(OH)₃ 胶体，吸附悬浮杂质沉降而净水；卤水点豆腐、江河入海口形成三角洲，都与聚沉有关。"}, {"h": "易错提醒", "p": "易错提醒：Fe(OH)₃ 胶体粒子能透过**滤纸**、不能透过**半透膜**；写制备方程式时漏写「胶体」二字或误加 ↓ 都会扣分。"}], "pitfalls": ["Fe(OH)₃ 胶体方程式误写 ↓ 或漏标「胶体」。", "制备时用自来水、过度加热、搅拌导致聚沉。", "把丁达尔效应的成因说成反射或折射（是散射）。"], "svg": "<rect x='20' y='55' width='70' height='30' rx='6' fill='#fef9c3'/><text x='55' y='75' text-anchor='middle' font-size='12'>光源</text><polygon points='90,62 250,45 250,95 90,78' fill='#fef08a' opacity='0.7'/><rect x='250' y='35' width='90' height='70' rx='6' fill='#fee2e2'/><text x='295' y='65' text-anchor='middle' font-size='12'>Fe(OH)₃ 胶体</text><text x='295' y='85' text-anchor='middle' font-size='11' fill='#64748b'>光亮通路</text>", "svgCap": "丁达尔效应：光束通过胶体时因粒子散射形成光亮通路。"}, "video": {"bvid": "BV1zK411674L", "p": 10, "t": "元素与物质分类(3)", "dur": "20:02", "from": 0, "vtop": ["分散系分类只看分散质粒子大小：小于 1 nm、1~100 nm、大于 100 nm。", "丁达尔效应是胶体的光学性质，是鉴别胶体与溶液最常用的方法。", "Fe(OH)₃ 胶体制备要煮沸、不能搅拌、不能加热过度。"], "vsum": "分散系是被分散的物质（**分散质**）分散在另一种物质（**分散剂**）中形成的混合物。按分散质粒子直径分：溶液小于 1 nm（均一稳定、能透过滤纸和**半透膜**），胶体 1~100 nm（较稳定、能透过滤纸不能透过半透膜），浊液大于 100 nm（不稳定、静置分层或沉降）。==胶体的招牌性质是丁达尔效应==；Fe(OH)₃ 胶体由饱和 FeCl₃ 溶液滴入沸水制得，能吸附悬浮物净水，加电解质、加热或加带相反电荷的胶体都会**聚沉**。\n易错提醒：区分溶液、胶体与浊液的本质是分散质粒子直径的大小，丁达尔效应只是胶体的性质而不是本质区别。", "vtech": ["看到鉴别胶体与溶液 → 首选丁达尔效应：一束光侧面看，胶体有光亮通路。", "看到粒子大小比较题 → 先把单位统一到 nm，再按 1 与 100 两个界限归类。"], "vgaokao": []}}, "chem_c016": {"name": "电解质与非电解质", "sec": 2, "secTitle": "电解质的电离 离子反应", "page": 53, "desc": "判据是水溶液或熔融状态能否导电、且导电靠自身电离；单质与混合物两不沾。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c017"], "content": {"advance": {"a": "固体中 Na⁺ 与 Cl⁻ 被固定在晶格中不能自由移动；溶于水或熔融时离子脱离晶格成为自由移动的离子，在电场下定向移动而导电。导电的本质是有自由移动的带电粒子。", "kind": "self", "q": "为什么 NaCl 固体不导电、水溶液和熔融 NaCl 却能导电？从微观粒子角度说明。"}, "apply": [{"ans": 3, "opts": ["强电解质一定易溶于水", "BaSO₄ 难溶于水，所以是弱电解质", "CH₃COOH 易溶于水，所以是强电解质", "强弱电解质的区别在于电离程度不同"], "q": "下列说法正确的是（ ）", "why": "强弱看电离是否完全，与溶解度无关：BaSO₄ 是强电解质，CH₃COOH 是弱电解质。"}], "basics": [{"ans": 2, "opts": ["铜", "盐酸", "熔融的 NaCl", "蔗糖"], "q": "下列物质属于电解质的是（ ）", "why": "熔融 NaCl 是能导电的化合物；铜是单质、盐酸是混合物、蔗糖是非电解质。"}, {"ans": 1, "opts": ["NH₃·H₂O", "CO₂", "BaSO₄", "KOH"], "q": "下列物质属于非电解质的是（ ）", "why": "CO₂ 自身不电离，水溶液导电靠生成的碳酸；其余均为电解质。"}], "case": {"a": "不对。SO₂ 是非电解质；溶液导电靠 H₂SO₃ 的电离，H₂SO₃ 才是电解质。", "hints": ["导电的离子是谁电离出来的？", "SO₂ 与水反应生成了什么？"], "q": "SO₂ 溶于水得到的溶液能导电，有人据此说 SO₂ 是电解质。对吗？说明理由，并指出该溶液中真正的电解质是什么。", "steps": ["SO₂ + H₂O ⇌ H₂SO₃，溶液中的离子是 H₂SO₃ 电离产生的，不是 SO₂ 自身电离。", "SO₂ 熔融状态也不导电，所以 SO₂ 是非电解质。", "该溶液中真正的电解质是 H₂SO₃（弱电解质）。"], "talk": ["这类题固定答法：指出导电离子的来源，不是自身电离就判非电解质。"], "title": "案例：SO₂ 水溶液能导电，它是电解质吗"}, "intro": "判断电解质有两个限定，少一个都会掉坑。==电解质是在水溶液里或熔融状态下能够导电的化合物。==注意「或」和「化合物」：这是本节全部陷阱的源头。", "learn": [{"h": "两个定义，一组对照", "p": "**电解质**：在**水溶液里或熔融状态下**能够导电的**化合物**；**非电解质**：在水溶液里**和**熔融状态下都不能导电的化合物。\n\n==电解质定义用「或」，非电解质定义用「和」——熔融能导电、水溶液不能导电的，仍是电解质。==如 BaSO₄ 熔融能导电，是电解质，尽管它难溶。"}, {"h": "导电必须靠自身电离", "p": "SO₂、CO₂、NH₃ 的水溶液都能导电，但导电的离子来自它们与水反应生成的酸，不是自身电离，所以三者都是**非电解质**，生成的 H₂SO₃、H₂CO₃、NH₃·H₂O 才是电解质。\n\n==判断口诀：先看是不是化合物，再看导电的离子是不是它自己电离出来的。==单质（如铜、石墨）和混合物（如盐酸）既不是电解质也不是非电解质。"}, {"h": "强弱电解质", "p": "在水溶液中**完全电离**的是**强电解质**（强酸、强碱、大多数盐，如 HCl、NaOH、NaCl）；**部分电离**的是**弱电解质**（弱酸、弱碱、水，如 CH₃COOH、NH₃·H₂O）。\n\n强弱看电离程度，与溶解度无关：BaSO₄ 难溶但溶解的部分完全电离，是强电解质；CH₃COOH 易溶但部分电离，是弱电解质。"}, {"h": "易错提醒", "p": "易错提醒：电解质导电的前提是电离出自由移动的离子；固体 NaCl 不导电，但它仍是电解质（溶于水或熔融时导电）。「不导电的物质一定是非电解质」是错误说法。"}], "pitfalls": ["水溶液导电就判电解质，不查离子来源（SO₂、CO₂、NH₃ 三连坑）。", "把单质、混合物硬塞进电解质或非电解质。", "用溶解度判断强弱电解质。"], "svg": "<rect x='120' y='10' width='120' height='28' rx='6' fill='#2563eb'/><text x='180' y='29' text-anchor='middle' font-size='12' fill='#fff'>化合物</text><rect x='20' y='65' width='130' height='30' rx='6' fill='#e0f2fe'/><text x='85' y='85' text-anchor='middle' font-size='12'>电解质：能导电</text><rect x='210' y='65' width='130' height='30' rx='6' fill='#fef3c7'/><text x='275' y='85' text-anchor='middle' font-size='12'>非电解质：都不导电</text><text x='180' y='118' text-anchor='middle' font-size='11' fill='#dc2626'>单质与混合物：两者都不是</text><line x1='155' y1='38' x2='90' y2='65' stroke='#94a3b8'/><line x1='205' y1='38' x2='270' y2='65' stroke='#94a3b8'/>", "svgCap": "电解质与非电解质的适用对象都是化合物；单质和混合物不在讨论范围内。"}, "video": {"bvid": "BV1zK411674L", "p": 11, "t": "电解质的电离 离子反应(1)", "dur": "20:17", "from": 0, "vtop": ["电解质与非电解质都是化合物，单质和混合物既不是电解质也不是非电解质。", "导电必须靠化合物自身电离出的离子，SO₂、NH₃ 的水溶液导电但它们是非电解质。", "强电解质完全电离用等号，弱电解质部分电离用可逆号。"], "vsum": "**电解质**：在水溶液里或熔融状态下能够导电的化合物；**非电解质**：在水溶液里和熔融状态下都不能导电的化合物。两个限定缺一不可——对象必须是化合物，==导电必须靠自身电离==。**强电解质**（强酸、强碱、大多数盐）完全电离，书写用等号；**弱电解质**（弱酸、弱碱、水）部分电离，用可逆号，多元弱酸分步电离、多元弱碱一步写。酸式盐的电离要分强弱：NaHSO₄ 在水中完全电离出 H⁺，NaHCO₃ 中的 HCO₃⁻ 只微弱电离。\n易错提醒：SO₂、CO₂、NH₃ 的水溶液虽然能导电，但导电靠的是它们与水反应生成的酸或碱电离，它们本身不是电解质。", "vtech": ["看到导电判断 → 连问三句：是化合物吗？导电靠自身电离吗？熔融时导电吗？", "看到电离方程式 → 先定强弱：强用等号全拆，弱用可逆号，多元弱酸分步。"], "vgaokao": []}}, "chem_c017": {"name": "电离与电离方程式", "sec": 2, "secTitle": "电解质的电离 离子反应", "page": 55, "desc": "强电解质完全电离用等号、弱电解质部分电离用可逆号；多元弱酸分步写。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c016"], "next": ["chem_c018"], "content": {"advance": {"a": "水中 HSO₄⁻ 的第二步电离程度较大，可近似完全电离出 H⁺，所以显强酸性；熔融状态下缺少水的促进，HSO₄⁻ 作为整体只电离出 Na⁺ 与 HSO₄⁻，不产生 H⁺。", "kind": "self", "q": "NaHSO₄ 为什么在水溶液中显强酸性、在熔融状态下却不能电离出 H⁺？"}, "apply": [{"ans": 1, "opts": ["0.1、0.1", "0.2、0.1", "0.1、0.2", "0.2、0.2"], "q": "0.1 mol/L 的 Na₂SO₄ 溶液中，Na⁺ 与 SO₄²⁻ 的浓度分别是（ ）", "why": "Na₂SO₄ ＝ 2Na⁺ + SO₄²⁻，离子浓度等于盐浓度乘下标：Na⁺ 为 0.2，SO₄²⁻ 为 0.1（单位 mol/L）。"}], "basics": [{"ans": 2, "opts": ["HCO₃⁻ ＝ H⁺ + CO₃²⁻", "AlCl₃ ＝ Al³⁺ + Cl⁻", "MgCl₂ ＝ Mg²⁺ + 2Cl⁻", "NaHSO₄（熔融）＝ Na⁺ + H⁺ + SO₄²⁻"], "q": "下列电离方程式正确的是（ ）", "why": "MgCl₂ 完全电离且守恒。A 应为可逆号；B 中 Cl⁻ 个数应为 3；D 熔融时 HSO₄⁻ 不拆。"}, {"ans": 1, "opts": ["H₂CO₃ ＝ 2H⁺ + CO₃²⁻", "H₂CO₃ ⇌ H⁺ + HCO₃⁻", "H₂CO₃ ⇌ 2H⁺ + CO₃²⁻", "HCO₃⁻ ⇌ H⁺ + CO₃²⁻"], "q": "H₂CO₃ 的第一步电离方程式是（ ）", "why": "多元弱酸分步电离，第一步生成 H⁺ 与 HCO₃⁻，用可逆号。"}], "case": {"a": "① 应为 H₂SO₄ ＝ 2H⁺ + SO₄²⁻；② 应为 NaHCO₃ ＝ Na⁺ + HCO₃⁻；③ 应为 CH₃COOH ⇌ CH₃COO⁻ + H⁺。", "hints": ["逐条查电荷守恒与电离程度。", "②想 NaHCO₃ 中 HCO₃⁻ 的电离程度。"], "q": "指出下列电离方程式的错误并改正：① H₂SO₄ ＝ H⁺ + SO₄²⁻；② NaHCO₃ ＝ Na⁺ + H⁺ + CO₃²⁻；③ CH₃COOH ＝ CH₃COO⁻ + H⁺。", "steps": ["① 电荷不守恒：H₂SO₄ ＝ 2H⁺ + SO₄²⁻，H⁺ 前系数应为 2。", "② HCO₃⁻ 是弱酸根，只微弱电离：NaHCO₃ ＝ Na⁺ + HCO₃⁻。", "③ CH₃COOH 是弱电解质，部分电离：CH₃COOH ⇌ CH₃COO⁻ + H⁺。"], "talk": ["改错题按三查走：查符号（＝还是 ⇌）、查系数下标、查电荷守恒，每条错误对应一查。"], "title": "案例：改错——三条电离方程式找毛病"}, "intro": "电离方程式是离子反应的前置技能，写错一步后面全错。==强电解质完全电离用「＝」，弱电解质部分电离用「⇌」。==再加一条：原子守恒与电荷守恒必须同时成立。", "learn": [{"h": "电离的概念", "p": "**电离**是电解质溶于水或受热熔化时，离解成自由移动的**离子**的过程。电离不需要通电，通电后的定向移动是导电。\n\n书写时左边写化学式，右边写离子符号，离子所带电荷数等于其化合价，个数由化学式下标决定。"}, {"h": "强电解质：一步到位", "p": "强酸、强碱、可溶盐完全电离：HCl ＝ H⁺ + Cl⁻；NaOH ＝ Na⁺ + OH⁻；Ba(OH)₂ ＝ Ba²⁺ + 2OH⁻；Al₂(SO₄)₃ ＝ 2Al³⁺ + 3SO₄²⁻。\n\n==系数与下标不能丢：离子个数错了，电荷就不守恒，一查便知。==如 MgCl₂ ＝ Mg²⁺ + 2Cl⁻，左边中性，右边 +2 与 2 个 −1 恰好抵消。"}, {"h": "弱电解质：分步与可逆", "p": "弱电解质用可逆号：CH₃COOH ⇌ CH₃COO⁻ + H⁺；NH₃·H₂O ⇌ NH₄⁺ + OH⁻。**多元弱酸分步电离**，以第一步为主：H₂CO₃ ⇌ H⁺ + HCO₃⁻，HCO₃⁻ ⇌ H⁺ + CO₃²⁻。\n\n多元弱碱通常一步写出，如 Fe(OH)₃ ⇌ Fe³⁺ + 3OH⁻（实际分步，习惯合并）。"}, {"h": "酸式盐的电离要分情况", "p": "**NaHSO₄** 在水中完全电离：NaHSO₄ ＝ Na⁺ + H⁺ + SO₄²⁻（HSO₄⁻ 视为完全电离）；在熔融状态下只电离出 Na⁺ 与 HSO₄⁻。**NaHCO₃** ＝ Na⁺ + HCO₃⁻，HCO₃⁻ 只微弱电离出 H⁺，不能拆成 H⁺ + CO₃²⁻。\n\n易错提醒：把 NaHCO₃ 的电离写成放出 H⁺ 是离子反应题最常见的连环错误源头。"}], "pitfalls": ["离子个数漏乘下标，导致电荷不守恒。", "弱电解质误用等号、多元弱酸一步写完。", "NaHCO₃ 与 NaHSO₄ 的电离写法混淆。"], "svg": "<rect x='15' y='35' width='100' height='32' rx='6' fill='#e0f2fe'/><text x='65' y='56' text-anchor='middle' font-size='12'>强电解质 ＝</text><rect x='130' y='35' width='100' height='32' rx='6' fill='#fef3c7'/><text x='180' y='56' text-anchor='middle' font-size='12'>弱电解质 ⇌</text><rect x='245' y='35' width='105' height='32' rx='6' fill='#fee2e2'/><text x='297' y='56' text-anchor='middle' font-size='12'>多元弱酸分步</text><text x='180' y='95' text-anchor='middle' font-size='11' fill='#64748b'>写完必查：原子守恒 + 电荷守恒</text>", "svgCap": "电离方程式的三种写法：强用等号、弱用可逆号、多元弱酸分步。"}, "video": {"bvid": "BV1zK411674L", "p": 11, "t": "电解质的电离 离子反应(1)", "dur": "20:17", "from": 0, "vtop": ["电解质与非电解质都是化合物，单质和混合物既不是电解质也不是非电解质。", "导电必须靠化合物自身电离出的离子，SO₂、NH₃ 的水溶液导电但它们是非电解质。", "强电解质完全电离用等号，弱电解质部分电离用可逆号。"], "vsum": "**电解质**：在水溶液里或熔融状态下能够导电的化合物；**非电解质**：在水溶液里和熔融状态下都不能导电的化合物。两个限定缺一不可——对象必须是化合物，==导电必须靠自身电离==。**强电解质**（强酸、强碱、大多数盐）完全电离，书写用等号；**弱电解质**（弱酸、弱碱、水）部分电离，用可逆号，多元弱酸分步电离、多元弱碱一步写。酸式盐的电离要分强弱：NaHSO₄ 在水中完全电离出 H⁺，NaHCO₃ 中的 HCO₃⁻ 只微弱电离。\n易错提醒：SO₂、CO₂、NH₃ 的水溶液虽然能导电，但导电靠的是它们与水反应生成的酸或碱电离，它们本身不是电解质。", "vtech": ["看到导电判断 → 连问三句：是化合物吗？导电靠自身电离吗？熔融时导电吗？", "看到电离方程式 → 先定强弱：强用等号全拆，弱用可逆号，多元弱酸分步。"], "vgaokao": []}}, "chem_c018": {"name": "离子反应与离子方程式的书写", "sec": 2, "secTitle": "电解质的电离 离子反应", "page": 59, "desc": "写、拆、删、查四步法：强酸强碱可溶盐拆，沉淀气体水弱电解质不拆。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c017"], "next": ["chem_c019"], "content": {"advance": {"a": "HCl+NaOH、HNO₃+KOH、HCl+KOH 三个化学方程式不同，但离子方程式都是 H⁺ + OH⁻ ＝ H₂O，说明中和的本质与具体的酸碱种类无关，只是 H⁺ 与 OH⁻ 结合生成水。离子方程式表示的是一类反应。", "kind": "self", "q": "为什么离子方程式比化学方程式更能揭示反应的本质？以三组不同的酸碱中和为例说明。"}, "apply": [{"ans": 1, "opts": ["HCO₃⁻ + OH⁻ ＝ CO₃²⁻ + H₂O", "Ca²⁺ + 2HCO₃⁻ + 2OH⁻ ＝ CaCO₃↓ + CO₃²⁻ + 2H₂O", "Ca²⁺ + HCO₃⁻ ＝ CaCO₃↓ + H⁺", "HCO₃⁻ + Ca²⁺ + OH⁻ ＝ CaCO₃↓ + H₂O（石灰水过量时）"], "q": "向 NaHCO₃ 溶液中滴加少量澄清石灰水，离子方程式书写时应以量少的物质为基准。少量石灰水对应的离子反应是（ ）", "why": "石灰水少量时 Ca²⁺ 与 OH⁻ 完全反应，按 Ca(OH)₂ 的组成 1∶2 消耗 HCO₃⁻；查电荷：左 +2−2−2＝−2，右 −2，守恒。D 是石灰水过量、以 HCO₃⁻ 为基准的写法。"}], "basics": [{"ans": 1, "opts": ["Fe + 2H⁺ ＝ Fe³⁺ + H₂↑", "CaCO₃ + 2H⁺ ＝ Ca²⁺ + H₂O + CO₂↑", "CO₃²⁻ + H⁺ ＝ H₂O + CO₂↑", "Cu + Ag⁺ ＝ Cu²⁺ + Ag"], "q": "下列离子方程式正确的是（ ）", "why": "CaCO₃ 不拆、产物守恒正确。A 中 Fe 与酸生成 Fe²⁺；C 中 H⁺ 系数应为 2 且电荷不守恒；D 中 Ag⁺ 系数应为 2。"}, {"ans": 1, "opts": ["CH₃COOH 与 NaOH", "HCl 与 Ba(OH)₂", "H₂SO₄ 与 KOH 生成 K₂SO₄ 时只考虑中和", "Cu(OH)₂ 与 HCl"], "q": "能用 H⁺ + OH⁻ ＝ H₂O 表示的反应是（ ）", "why": "强酸与强碱反应生成可溶盐时可用该式。A 中 CH₃COOH 不拆；D 中 Cu(OH)₂ 不拆。"}], "case": {"a": "Cu²⁺ + SO₄²⁻ + Ba²⁺ + 2OH⁻ ＝ Cu(OH)₂↓ + BaSO₄↓；漏写 BaSO₄ 生成即不完整。", "hints": ["数一数生成物：只有氢氧化铜一种沉淀吗？", "Ba²⁺ 与 SO₄²⁻ 去哪了？"], "q": "写出 CuSO₄ 溶液与 Ba(OH)₂ 溶液反应的离子方程式，并说明只写 Cu²⁺ + 2OH⁻ ＝ Cu(OH)₂↓ 为什么不完整。", "steps": ["化学方程式：CuSO₄ + Ba(OH)₂ ＝ Cu(OH)₂↓ + BaSO₄↓，生成两种沉淀。", "拆：Cu²⁺、SO₄²⁻、Ba²⁺、OH⁻ 全部拆开；删：无相同离子可删。", "离子方程式：Cu²⁺ + SO₄²⁻ + Ba²⁺ + 2OH⁻ ＝ Cu(OH)₂↓ + BaSO₄↓。", "查电荷：左侧 +2−2+2−2＝0，右侧 0，守恒；只写 Cu(OH)₂ 一步漏掉了 BaSO₄ 的生成。"], "talk": ["两个反应同时发生的题，要把所有实际参与的离子都留下；判断标准是离子浓度是否减小。"], "title": "案例：CuSO₄ 与 Ba(OH)₂ 反应，为什么不能只写一步"}, "intro": "离子方程式只保留真正参与反应的离子，是本章的得分主战场。==书写四步：写、拆、删、查。==最后一步「查」专门查两件事：原子守恒与电荷守恒。", "learn": [{"h": "离子反应的条件", "p": "**离子反应**是电解质在溶液中以离子形式参与的反应，发生的条件是生成**沉淀、气体、水（或弱电解质）**，或发生**氧化还原反应**——本质是某种离子的浓度显著减小。\n\n如 Ba²⁺ + SO₄²⁻ ＝ BaSO₄↓，溶液中这两种离子几乎被消耗完，反应才能进行到底。"}, {"h": "四步法与拆写规则", "p": "写：写出正确的化学方程式；拆：把**强酸、强碱、可溶性盐**拆成离子，其余（难溶物、气体、水、弱电解质、单质、氧化物）保留化学式；删：删去两边相同离子；查：查守恒与最简比。\n\n==能拆的只有三类：强酸、强碱、可溶盐；见到沉淀、气体、水、醋酸、氨水、氧化物，一律不拆。==CaCO₃ + 2H⁺ ＝ Ca²⁺ + H₂O + CO₂↑ 中 CaCO₃ 保留化学式。"}, {"h": "典型离子方程式要成组记", "p": "酸碱中和的代表式：H⁺ + OH⁻ ＝ H₂O（仅限强酸与强碱生成可溶盐时）。沉淀类：Ag⁺ + Cl⁻ ＝ AgCl↓；Ba²⁺ + CO₃²⁻ ＝ BaCO₃↓。气体类：CO₃²⁻ + 2H⁺ ＝ H₂O + CO₂↑；NH₄⁺ + OH⁻ ＝(加热) NH₃↑ + H₂O。\n\n注意 H₂SO₄ 与 Ba(OH)₂ 反应不能只写 H⁺ + OH⁻：Ba²⁺ + SO₄²⁻ + 2H⁺ + 2OH⁻ ＝ BaSO₄↓ + 2H₂O，两种沉淀与水的生成一个都不能漏。"}, {"h": "易错提醒", "p": "易错提醒：微溶物（如 Ca(OH)₂ 澄清石灰水）作反应物时拆、作生成物时写化学式；浓硫酸参与反应时以分子形式写，不能拆成离子（浓 H₂SO₄ 主要以分子存在）。"}], "pitfalls": ["沉淀、气体、水、弱电解质误拆成离子。", "漏查电荷守恒，系数配错（如 Ag⁺、H⁺ 前系数）。", "两种沉淀同时生成的反应只写一半。"], "svg": "<rect x='8' y='45' width='70' height='30' rx='6' fill='#e0f2fe'/><text x='43' y='65' text-anchor='middle' font-size='12'>写方程式</text><rect x='98' y='45' width='70' height='30' rx='6' fill='#e0f2fe'/><text x='133' y='65' text-anchor='middle' font-size='12'>拆强电解质</text><rect x='188' y='45' width='70' height='30' rx='6' fill='#e0f2fe'/><text x='223' y='65' text-anchor='middle' font-size='12'>删相同离子</text><rect x='278' y='45' width='74' height='30' rx='6' fill='#dbeafe'/><text x='315' y='65' text-anchor='middle' font-size='12'>查守恒</text><text x='85' y='65' font-size='13'>→</text><text x='175' y='65' font-size='13'>→</text><text x='265' y='65' font-size='13'>→</text>", "svgCap": "离子方程式书写四步法：写、拆、删、查。"}, "video": {"bvid": "BV1zK411674L", "p": 12, "t": "电解质的电离 离子反应(2)", "dur": "20:28", "from": 0, "vtop": ["离子方程式四步：写、拆、删、查（查原子守恒与电荷守恒）。", "能拆的只有强酸、强碱和可溶性盐；沉淀、气体、水、弱电解质、氧化物都不拆。", "离子不能大量共存的四种情形：生成沉淀、气体、水（或弱电解质）、发生氧化还原反应。"], "vsum": "**离子反应**是电解质在溶液中以离子形式参与的反应，==离子方程式只写实际参与反应的离子==。书写四步：写出化学方程式；把**强酸、强碱、可溶性盐**拆成离子，难溶物、气体、水、弱电解质、单质、氧化物保留化学式；删去两边相同的离子；检查**原子守恒**、**电荷守恒**和最简整数比。离子共存抓四条禁令，离子检验抓试剂与现象的对应：如 SO₄²⁻ 用盐酸酸化后加 BaCl₂，Cl⁻ 用 AgNO₃ 与稀硝酸，NH₄⁺ 用浓 NaOH 加热并用湿润红色石蕊试纸检验。\n易错提醒：检验 SO₄²⁻ 时要先加盐酸酸化排除 CO₃²⁻ 等干扰，再加 BaCl₂ 观察白色沉淀。", "vtech": ["写离子方程式 → 默念「写拆删查」，最后一步专门查电荷是否守恒、最简比是否约掉。", "看到离子共存题 → 按沉淀、气体、水、氧化还原四张清单逐对排查。", "看到「与量有关」的离子反应 → 先判断谁过量，过量者满足化学计量、少量者完全反应。"], "vgaokao": []}}, "chem_c019": {"name": "离子共存与常见离子检验", "sec": 2, "secTitle": "电解质的电离 离子反应", "page": 62, "desc": "生成沉淀、气体、水或发生氧化还原就不能大量共存；常见离子的检验试剂与现象。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c018"], "next": [], "content": {"advance": {"a": "若溶液含 SO₃²⁻，稀硝酸会把 SO₃²⁻ 氧化为 SO₄²⁻，再加 BaCl₂ 同样出现白色沉淀，造成假阳性。用盐酸酸化没有氧化性，可避免这一干扰。", "kind": "self", "q": "检验 SO₄²⁻ 时为什么不能用稀硝酸代替稀盐酸做酸化剂？（提示：想想 SO₃²⁻ 在强氧化性酸中的变化）"}, "apply": [{"ans": 2, "opts": ["只有 SO₄²⁻", "只有 CO₃²⁻", "SO₄²⁻ 与 CO₃²⁻", "Ag⁺ 与 SO₄²⁻"], "q": "某无色溶液加入 BaCl₂ 产生白色沉淀，再加稀硝酸沉淀部分溶解并产生气泡。该溶液可能含有（ ）", "why": "不溶于硝酸的部分是 BaSO₄，溶解并放气的是 BaCO₃ 遇酸放 CO₂，说明 SO₄²⁻ 与 CO₃²⁻ 并存。"}], "basics": [{"ans": 2, "opts": ["Na⁺、K⁺、CO₃²⁻、Cl⁻", "Ba²⁺、Na⁺、SO₄²⁻、Cl⁻", "Mg²⁺、Na⁺、SO₄²⁻、Cl⁻", "Cu²⁺、K⁺、SO₄²⁻、NO₃⁻"], "q": "在强酸性无色溶液中能大量共存的一组离子是（ ）", "why": "A 中 CO₃²⁻ 与 H⁺ 反应；B 中 BaSO₄ 沉淀；D 中 Cu²⁺ 有颜色且题干要求无色。C 各离子互不反应。"}, {"ans": 1, "opts": ["BaCl₂ 与盐酸", "AgNO₃ 与稀硝酸", "盐酸与澄清石灰水", "NaOH 与红色石蕊试纸"], "q": "检验 Cl⁻ 选用的试剂是（ ）", "why": "AgCl 是不溶于稀硝酸的白色沉淀，这是 Cl⁻ 的特征检验。"}], "case": {"a": "先盐酸酸化排干扰，再加 BaCl₂，出现不溶于酸的白色沉淀则含 SO₄²⁻。", "hints": ["先想干扰：Ba²⁺ 与 CO₃²⁻ 也生成白色沉淀，Ag⁺ 也来捣乱。", "酸化的酸要选对：不能引入 SO₄²⁻ 或待检离子。"], "q": "某溶液可能含 SO₄²⁻、CO₃²⁻、Cl⁻ 中的一种或多种。设计检验 SO₄²⁻ 是否存在的方案，并说明每一步的目的。", "steps": ["取少量溶液，先滴加足量稀盐酸酸化：CO₃²⁻ 与 H⁺ 反应放出气体被除去，避免它与 Ba²⁺ 生成 BaCO₃ 白色沉淀冒充 BaSO₄。", "再滴加 BaCl₂ 溶液，若出现白色沉淀，则该沉淀只能是 BaSO₄。", "结论：原溶液中含有 SO₄²⁻。注意酸化用盐酸不用硝酸，防止 SO₃²⁻ 被氧化成 SO₄²⁻ 造成假阳性。"], "talk": ["检验题答三段：试剂、现象、结论，并点名排除的干扰离子，顺序写反直接判错。"], "title": "案例：检验未知溶液中是否含 SO₄²⁻"}, "intro": "离子共存题的本质是反着用离子反应：能反应的就不能共存。==四张禁令清单：生成沉淀、生成气体、生成水或弱电解质、发生氧化还原反应。==离子检验则是正着用：选试剂、看现象、下结论。", "learn": [{"h": "不能共存的四种情形", "p": "生成**沉淀**：如 Ba²⁺ 与 SO₄²⁻、Ag⁺ 与 Cl⁻、Ca²⁺ 与 CO₃²⁻；生成**气体**：CO₃²⁻、HCO₃⁻、S²⁻ 与 H⁺，NH₄⁺ 与 OH⁻（加热更明显）；生成**水或弱电解质**：H⁺ 与 OH⁻、H⁺ 与 CH₃COO⁻、H⁺ 与 F⁻；发生**氧化还原**：Fe³⁺ 与 S²⁻、酸性条件下 MnO₄⁻ 与 Cl⁻ 等。\n\n==做共存题不要逐个离子想，要逐对排查组合。=="}, {"h": "附加条件别漏看", "p": "题干常藏条件：**无色溶液**排除 Cu²⁺（蓝）、Fe³⁺（黄）、Fe²⁺（浅绿）、MnO₄⁻（紫红）；**酸性溶液**意味着有大量 H⁺，碱性溶液意味着有大量 OH⁻，要把隐含离子一起排查。\n\n如酸性条件下 CO₃²⁻、HCO₃⁻、OH⁻ 都不能大量存在。"}, {"h": "常见离子检验表", "p": "**SO₄²⁻**：先加盐酸酸化（排除 Ag⁺、CO₃²⁻ 干扰），再加 BaCl₂，出现不溶于酸的白色沉淀；**Cl⁻**：加 AgNO₃ 与稀硝酸，白色沉淀不溶于硝酸；**CO₃²⁻**：加盐酸产生使澄清石灰水变浑浊的气体；**NH₄⁺**：加浓 NaOH 并加热，用湿润的红色石蕊试纸检验放出的 NH₃（试纸变蓝）；**Fe³⁺**：加 KSCN 溶液变红。\n\n==检验讲究顺序与排干扰：查 SO₄²⁻ 必须先酸化，否则 BaCO₃ 也会冒充白色沉淀。=="}, {"h": "易错提醒", "p": "易错提醒：「大量共存」不等于少量能共存的离子对可以含糊过关；微溶物的离子对在浓度大时按沉淀处理。另外 HCO₃⁻ 与 H⁺、OH⁻ 都反应，是共存题的高频双面坑。"}], "pitfalls": ["共存题漏看无色、酸性、碱性等附加条件。", "检验 SO₄²⁻ 不先酸化，被 CO₃²⁻ 干扰误判。", "HCO₃⁻ 与 H⁺、OH⁻ 均反应这一点被遗漏。"], "svg": "<rect x='15' y='30' width='75' height='28' rx='6' fill='#fee2e2'/><text x='52' y='49' text-anchor='middle' font-size='12'>生成沉淀</text><rect x='102' y='30' width='75' height='28' rx='6' fill='#fee2e2'/><text x='139' y='49' text-anchor='middle' font-size='12'>生成气体</text><rect x='189' y='30' width='75' height='28' rx='6' fill='#fee2e2'/><text x='226' y='49' text-anchor='middle' font-size='12'>生成水</text><rect x='276' y='30' width='75' height='28' rx='6' fill='#fee2e2'/><text x='313' y='49' text-anchor='middle' font-size='12'>氧化还原</text><text x='183' y='85' text-anchor='middle' font-size='12'>四种情形命中其一 → 不能大量共存</text>", "svgCap": "离子不能大量共存的四种情形，共存题按此清单逐对排查。"}, "video": {"bvid": "BV1zK411674L", "p": 12, "t": "电解质的电离 离子反应(2)", "dur": "20:28", "from": 0, "vtop": ["离子方程式四步：写、拆、删、查（查原子守恒与电荷守恒）。", "能拆的只有强酸、强碱和可溶性盐；沉淀、气体、水、弱电解质、氧化物都不拆。", "离子不能大量共存的四种情形：生成沉淀、气体、水（或弱电解质）、发生氧化还原反应。"], "vsum": "**离子反应**是电解质在溶液中以离子形式参与的反应，==离子方程式只写实际参与反应的离子==。书写四步：写出化学方程式；把**强酸、强碱、可溶性盐**拆成离子，难溶物、气体、水、弱电解质、单质、氧化物保留化学式；删去两边相同的离子；检查**原子守恒**、**电荷守恒**和最简整数比。离子共存抓四条禁令，离子检验抓试剂与现象的对应：如 SO₄²⁻ 用盐酸酸化后加 BaCl₂，Cl⁻ 用 AgNO₃ 与稀硝酸，NH₄⁺ 用浓 NaOH 加热并用湿润红色石蕊试纸检验。\n易错提醒：检验 SO₄²⁻ 时要先加盐酸酸化排除 CO₃²⁻ 等干扰，再加 BaCl₂ 观察白色沉淀。", "vtech": ["写离子方程式 → 默念「写拆删查」，最后一步专门查电荷是否守恒、最简比是否约掉。", "看到离子共存题 → 按沉淀、气体、水、氧化还原四张清单逐对排查。", "看到「与量有关」的离子反应 → 先判断谁过量，过量者满足化学计量、少量者完全反应。"], "vgaokao": []}}, "chem_c020": {"name": "氧化还原反应与化合价升降", "sec": 3, "secTitle": "氧化还原反应", "page": 66, "desc": "本质是电子转移，特征是化合价升降；升失氧、降得还，口诀要连对象一起记。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": [], "next": ["chem_c021"], "content": {"advance": {"a": "复分解反应只是两种化合物互相交换成分生成另外两种化合物，各元素化合价在反应前后保持不变，没有化合价升降，也就没有电子转移，所以一定不是氧化还原反应。", "kind": "self", "q": "为什么复分解反应一定不是氧化还原反应？从定义出发说明。"}, "apply": [{"ans": 2, "opts": ["Na", "O", "Cl 中一部分由 0 升到 +1", "H"], "q": "在 Cl₂ + 2NaOH ＝ NaCl + NaClO + H₂O 中，被氧化的元素是（ ）", "why": "Cl 一部分降到 −1（被还原），一部分升到 +1（被氧化），是歧化反应；Na、O、H 均不变价。"}], "basics": [{"ans": 2, "opts": ["CaCO₃ ＝(高温) CaO + CO₂↑", "NaOH + HCl ＝ NaCl + H₂O", "Zn + H₂SO₄（稀）＝ ZnSO₄ + H₂↑", "CaO + H₂O ＝ Ca(OH)₂"], "q": "下列反应属于氧化还原反应的是（ ）", "why": "Zn 由 0 升到 +2、H 由 +1 降到 0，有化合价升降；其余三项均无化合价变化。"}, {"ans": 3, "opts": ["+2", "+4", "+6", "+7"], "q": "KMnO₄ 中 Mn 元素的化合价是（ ）", "why": "K 为 +1、O 为 −2，设 Mn 为 x：1 + x + 4×(−2) ＝ 0，x ＝ +7。"}], "case": {"a": "氧化剂 Fe₂O₃、还原剂 CO、氧化产物 CO₂、还原产物 Fe。", "hints": ["先逐个标化合价，只看变价的 Fe 与 C。", "沿概念链走：谁降谁升。"], "q": "Fe₂O₃ + 3CO ＝(高温) 2Fe + 3CO₂ 中，指出氧化剂、还原剂、氧化产物、还原产物，并说明判断依据。", "steps": ["标价：Fe 由 +3 降到 0，C 由 +2 升到 +4，O 不变价。", "Fe 降得还：Fe₂O₃ 得电子、被还原，是氧化剂，对应还原产物 Fe。", "C 升失氧：CO 失电子、被氧化，是还原剂，对应氧化产物 CO₂。", "电子守恒核对：2 个 Fe 共降 6，3 个 C 共升 6，相等。"], "talk": ["概念题统一流程：标价→定升降→走链条→守恒核对，四步缺一不可。"], "title": "案例：给 Fe₂O₃ + 3CO 的每个概念落位"}, "intro": "氧化还原是高中化学的第一条主线，它的判断标准只有一个。==有元素化合价升降的反应，就是氧化还原反应；化合价升降的本质是电子转移。==先会标化合价，后面一切概念都顺着这条线走。", "learn": [{"h": "从得氧失氧到化合价升降", "p": "初中按得氧失氧判断：得氧被氧化、失氧被还原，范围太窄。高中标准升级为**化合价**：CuO + H₂ ＝(加热) Cu + H₂O 中，Cu 由 +2 降到 0，H 由 0 升到 +1。\n\n==凡是有化合价升降的反应都是氧化还原反应，与是否涉及氧无关。==如 Zn + 2HCl ＝ ZnCl₂ + H₂↑ 没有氧参与，同样是氧化还原反应。"}, {"h": "化合价口诀与标价方法", "p": "常见固定价：K、Na、Ag、H 为 +1，Ca、Mg、Zn、Ba 为 +2，Al 为 +3，O 通常 −2，Cl 通常 −1；**单质中元素化合价为 0**；化合物中各元素化合价代数和为 **0**，离子中代数和等于离子电荷。\n\n标价顺序：先写固定价，再用代数和为零推未知价，如 H₂SO₄ 中 S 为 +6，MnO₄⁻ 中 Mn 为 +7。"}, {"h": "升失氧、降得还：一条链记全", "p": "**化合价升高 → 失去电子 → 被氧化 → 发生氧化反应 → 该物质是还原剂 → 对应氧化产物**；反过来，化合价降低 → 得到电子 → 被还原 → 该物质是氧化剂 → 对应还原产物。\n\n==最容易错位的是「剂」的归属：还原剂被氧化，氧化剂被还原，动作与名称正好交叉。==记成「还原剂升失氧」——还原剂自己升价、失电子、被氧化。"}, {"h": "与四种基本反应类型的关系", "p": "**置换反应**一定是氧化还原反应；**化合、分解反应**部分是（有单质参加或生成的才是）；**复分解反应**一定不是（只有离子互换、无化合价变化）。\n\n易错提醒：有单质参加或生成的化合、分解反应才有化合价变化，如 CaO + H₂O ＝ Ca(OH)₂ 就不是氧化还原反应。"}], "pitfalls": ["「剂」的归属记反：还原剂被氧化、氧化剂被还原。", "用得氧失氧的老标准判断无氧参与的反应。", "化合价标错：单质为 0、过氧化物中 O 为 −1 等特殊价漏记。"], "svg": "<rect x='20' y='30' width='150' height='34' rx='6' fill='#fee2e2'/><text x='95' y='52' text-anchor='middle' font-size='12'>升高 失电子 被氧化</text><rect x='195' y='30' width='150' height='34' rx='6' fill='#e0f2fe'/><text x='270' y='52' text-anchor='middle' font-size='12'>降低 得电子 被还原</text><text x='95' y='90' text-anchor='middle' font-size='12'>还原剂 → 氧化产物</text><text x='270' y='90' text-anchor='middle' font-size='12'>氧化剂 → 还原产物</text>", "svgCap": "氧化还原概念链：升失氧对应还原剂，降得还对应氧化剂，名称与动作交叉。"}, "video": {"bvid": "BV1zK411674L", "p": 14, "t": "氧化还原反应(1)", "dur": "23:17", "from": 0, "vtop": ["氧化还原反应的本质是电子转移，特征是元素化合价发生变化。", "口诀连对象记：升（化合价升高）失（失电子）氧（被氧化、是还原剂）。", "四种基本反应类型与氧化还原有交叉：置换一定是，化合分解部分是，复分解一定不是。"], "vsum": "氧化还原反应以==化合价升降为特征、以电子转移为本质==。判断三步：标化合价、看升降、定概念——化合价升高、失去电子、被氧化、该物质是**还原剂**、对应氧化产物；化合价降低、得到电子、被还原、该物质是**氧化剂**、对应还原产物。**双线桥**从反应物指向产物，桥上写清得失电子数与化合价变化。常见氧化剂有浓硫酸、硝酸、KMnO₄、Cl₂、Fe³⁺ 等，常见还原剂有金属单质、C、H₂、CO、Fe²⁺、S²⁻ 等，**中间价态**物质如 Fe²⁺、SO₂ 既有氧化性又有还原性。\n易错提醒：还原剂被氧化、氧化剂被还原，「剂」的名称与它自身发生的反应正好相反，最容易记反。", "vtech": ["看到氧化还原判断 → 先标化合价，有升有降才是；只有升或只有降的题干必有错。", "看到概念辨析 → 沿一条线走完：价态变化→得失电子→被氧化被还原→剂与产物，别跳步。"], "vgaokao": []}}, "chem_c021": {"name": "氧化剂、还原剂与电子转移", "sec": 3, "secTitle": "氧化还原反应", "page": 69, "desc": "氧化剂得电子化合价降低、还原剂失电子化合价升高；双线桥标清电子转移数目。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c020"], "next": ["chem_c022", "chem_c023"], "content": {"advance": {"a": "Fe 为 +2 中间价：向上可升到 +3（被氧化、作还原剂，如遇 Cl₂、酸性 KMnO₄），向下可降到 0（被还原、作氧化剂，如遇 Zn 等活泼金属）。价态居中决定了它两性兼有。", "kind": "self", "q": "Fe²⁺ 为什么既能做还原剂又能做氧化剂？各举一个反应方向说明（只写离子或物质变化方向即可）。"}, "apply": [{"ans": 0, "opts": ["Fe³⁺ 强于 Cu²⁺", "Cu²⁺ 强于 Fe³⁺", "Cu 强于 Fe²⁺", "无法比较"], "q": "根据反应 Cu + 2Fe³⁺ ＝ Cu²⁺ + 2Fe²⁺，氧化性强弱顺序正确的是（ ）", "why": "氧化剂 Fe³⁺ 的氧化性强于氧化产物 Cu²⁺；这是强弱律的直接应用。"}], "basics": [{"ans": 1, "opts": ["Fe²⁺", "H₂SO₄（浓）中 +6 价的 S", "SO₂", "Cl⁻"], "q": "下列物质中只有氧化性的是（ ）", "why": "S 为 +6 最高价只能降价，只有氧化性；Fe²⁺、SO₂ 中 S（+4）为中间价，两性兼有；Cl⁻ 为最低价只有还原性。"}, {"ans": 1, "opts": ["3e⁻", "6e⁻", "2e⁻", "12e⁻"], "q": "在反应 2Al + 6HCl ＝ 2AlCl₃ + 3H₂↑ 中，转移电子总数是（ ）", "why": "Al 由 0 升到 +3，每个失 3e⁻，2 个 Al 共失 6e⁻；H 得电子总数同样为 6e⁻。"}], "case": {"a": "氧化剂 MnO₂、还原剂是被氧化的那一半 HCl；转移 2e⁻；被氧化的 HCl 占 1/2。", "hints": ["先分清 4 个 Cl 的去向：2 个进 Cl₂，2 个进 MnCl₂。", "还原剂只算真正被氧化的那部分 HCl。"], "q": "MnO₂ + 4HCl（浓）＝(加热) MnCl₂ + Cl₂↑ + 2H₂O 中，氧化剂与还原剂各是什么？转移电子总数是多少？被氧化的 HCl 占全部 HCl 的几分之几？", "steps": ["Mn 由 +4 降到 +2：MnO₂ 是氧化剂，得 2e⁻。", "Cl 由 −1 升到 0 的只有 2 个：这部分 HCl 是还原剂，失 2e⁻；另 2 个 Cl 化合价不变，只起酸的作用。", "转移电子总数为 2e⁻（每生成 1 个 Cl₂ 分子）。", "被氧化的 HCl 是 2 个，占全部 4 个 HCl 的二分之一。"], "talk": ["同一种物质身兼两职（还原剂＋酸）时要拆开算：变价的归氧化还原，不变价的归酸碱。"], "title": "案例：实验室制 Cl₂ 的电子转移要数对"}, "intro": "这一节把氧化还原算清楚：谁给了电子、给了几个、谁收了。==氧化剂与还原剂的强弱看得失电子的难易，不看数目的多少。==双线桥是把电子转移画出来的标准工具。", "learn": [{"h": "氧化剂与还原剂的判定再巩固", "p": "**氧化剂**：得到电子、化合价降低、被还原、发生还原反应，产物是**还原产物**；**还原剂**：失去电子、化合价升高、被氧化、发生氧化反应，产物是**氧化产物**。\n\n常见氧化剂：**Cl₂、O₂、浓 H₂SO₄、HNO₃、KMnO₄、Fe³⁺**；常见还原剂：**活泼金属、C、H₂、CO、Fe²⁺、S²⁻、I⁻**。"}, {"h": "双线桥：电子转移可视化", "p": "以 Zn + CuSO₄ ＝ ZnSO₄ + Cu 为例：一条桥从 Zn 指向产物中的 Zn²⁺，桥上写「失去 2e⁻，化合价升高，被氧化」；另一条桥从 Cu²⁺ 指向 Cu，写「得到 2e⁻，化合价降低，被还原」。\n\n==双线桥两端必须是同一种元素：起点在反应物、终点在生成物，桥上注明得失电子总数。==得失总数必须相等，这是配平与计算的依据。"}, {"h": "电子转移数目的算法", "p": "一个原子得失电子数 ＝ **化合价变化量**；总数 ＝ 变化量 × **变价原子个数**。如 MnO₂ + 4HCl（浓）＝(加热) MnCl₂ + Cl₂↑ + 2H₂O：Mn 由 +4 降到 +2，每个得 2e⁻，共 1 个 Mn 得 2e⁻；Cl 由 −1 升到 0，只有 2 个 Cl 变价（另 2 个仍在 MnCl₂ 中为 −1），共失 2e⁻。\n\n==最常见的错误是把 4 个 Cl 全算成变价——只有生成 Cl₂ 的那 2 个 Cl 化合价变了。=="}, {"h": "中间价态：两性兼有", "p": "元素处于**最高价**只有氧化性，处于**最低价**只有还原性，处于**中间价态**既有氧化性又有还原性。如 Fe²⁺、SO₂、H₂O₂ 都是中间价态代表：Fe²⁺ 遇强氧化剂被氧化成 Fe³⁺，遇强还原剂可被还原成 Fe。\n\n易错提醒：判断某物质在具体反应中是氧化剂还是还原剂，要看它实际的化合价变化方向，不能只背名单。"}], "pitfalls": ["转移电子数漏乘变价原子个数，或把未变价的原子也算进去。", "双线桥两端元素不一致、得失数目写成单原子数。", "强弱与得失电子数目挂钩（应看难易程度）。"], "svg": "<rect x='30' y='20' width='80' height='28' rx='6' fill='#fef3c7'/><text x='70' y='39' text-anchor='middle' font-size='12'>Zn（0）</text><rect x='250' y='20' width='80' height='28' rx='6' fill='#e0f2fe'/><text x='290' y='39' text-anchor='middle' font-size='12'>Zn²⁺（+2）</text><rect x='30' y='85' width='80' height='28' rx='6' fill='#e0f2fe'/><text x='70' y='104' text-anchor='middle' font-size='12'>Cu²⁺（+2）</text><rect x='250' y='85' width='80' height='28' rx='6' fill='#fef3c7'/><text x='290' y='104' text-anchor='middle' font-size='12'>Cu（0）</text><path d='M110 30 Q180 5 250 30' stroke='#dc2626' fill='none'/><text x='180' y='12' text-anchor='middle' font-size='11' fill='#dc2626'>失 2e⁻ 被氧化</text><path d='M110 99 Q180 124 250 99' stroke='#2563eb' fill='none'/><text x='180' y='128' text-anchor='middle' font-size='11' fill='#2563eb'>得 2e⁻ 被还原</text>", "svgCap": "双线桥示例（Zn + Cu²⁺）：两桥分别标注失去与得到 2e⁻，总数相等。"}, "video": {"bvid": "BV1zK411674L", "p": 14, "t": "氧化还原反应(1)", "dur": "23:17", "from": 0, "vtop": ["氧化还原反应的本质是电子转移，特征是元素化合价发生变化。", "口诀连对象记：升（化合价升高）失（失电子）氧（被氧化、是还原剂）。", "四种基本反应类型与氧化还原有交叉：置换一定是，化合分解部分是，复分解一定不是。"], "vsum": "氧化还原反应以==化合价升降为特征、以电子转移为本质==。判断三步：标化合价、看升降、定概念——化合价升高、失去电子、被氧化、该物质是**还原剂**、对应氧化产物；化合价降低、得到电子、被还原、该物质是**氧化剂**、对应还原产物。**双线桥**从反应物指向产物，桥上写清得失电子数与化合价变化。常见氧化剂有浓硫酸、硝酸、KMnO₄、Cl₂、Fe³⁺ 等，常见还原剂有金属单质、C、H₂、CO、Fe²⁺、S²⁻ 等，**中间价态**物质如 Fe²⁺、SO₂ 既有氧化性又有还原性。\n易错提醒：还原剂被氧化、氧化剂被还原，「剂」的名称与它自身发生的反应正好相反，最容易记反。", "vtech": ["看到氧化还原判断 → 先标化合价，有升有降才是；只有升或只有降的题干必有错。", "看到概念辨析 → 沿一条线走完：价态变化→得失电子→被氧化被还原→剂与产物，别跳步。"], "vgaokao": []}}, "chem_c022": {"name": "氧化还原反应的规律与配平入门", "sec": 3, "secTitle": "氧化还原反应", "page": 72, "desc": "守恒律、价态律、强弱律与先后律；配平抓手是化合价升降总数相等。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c021"], "next": [], "content": {"advance": {"a": "归中反应中高价只能降、低价只能升，产物价态必在两者之间且不能越过对方价态：如 +4 与 −2 归中只能到 0，不能出现高价降到比低价升后更低的交叉结果。相邻价态之间没有可归中的中间价态空间，故不发生此类氧化还原反应。", "kind": "self", "q": "为什么同种元素相邻价态之间（如 Fe²⁺ 与 Fe³⁺ 的相互转化设想、SO₂ 中 +4 价 S 与 +6 价 S）不能发生「价态越过」的反应？用价态律说明归中产物价态的范围。"}, "apply": [{"ans": 1, "opts": ["8∶3", "2∶3", "3∶2", "2∶8"], "q": "配平后 Cu + HNO₃（稀）反应中氧化剂与还原剂的物质的量之比是（ ）（方程式见正文案例推导：3Cu + 8HNO₃ ＝ 3Cu(NO₃)₂ + 2NO↑ + 4H₂O，其中作氧化剂的 HNO₃ 只计被还原的部分）", "why": "8 个 HNO₃ 中只有生成 NO 的 2 个被还原、是氧化剂；Cu 为还原剂 3 个，比值为 2∶3。成盐的 6 个 HNO₃ 只起酸的作用。"}], "basics": [{"ans": 1, "opts": ["Zn + CuSO₄ ＝ ZnSO₄ + Cu", "Cl₂ + 2NaOH ＝ NaCl + NaClO + H₂O", "SO₂ + 2H₂S ＝ 3S + 2H₂O", "Fe + 2HCl ＝ FeCl₂ + H₂↑"], "q": "下列反应属于歧化反应的是（ ）", "why": "Cl 由 0 同时升到 +1、降到 −1，是歧化；C 是归中，A、D 是普通置换。"}, {"ans": 1, "opts": ["Fe²⁺", "I⁻", "两者同时", "无法判断"], "q": "已知氧化性 Fe³⁺ 强于 I₂，向 FeI₂ 溶液中通入少量 Cl₂，先被氧化的离子是（ ）", "why": "还原性 I⁻ 强于 Fe²⁺，按先后律 Cl₂ 先氧化还原性最强的 I⁻。"}], "case": {"a": "2Al + 6HCl ＝ 2AlCl₃ + 3H₂↑，转移电子 6e⁻。", "hints": ["Al 升 3、H 降 1，最小公倍数是 6。", "先定 Al 与 H₂ 的系数，再配 HCl 与 AlCl₃。"], "q": "用化合价升降法配平 Al + HCl → AlCl₃ + H₂↑，并写出转移电子总数。", "steps": ["标价：Al 0→+3 升 3；H +1→0 降 1。", "升降相等：Al 配 2（共升 6），H₂ 配 3（共降 6）。", "配其余：AlCl₃ 配 2，HCl 配 6。", "查：2Al + 6HCl ＝ 2AlCl₃ + 3H₂↑，原子与电子均守恒，转移 6e⁻。"], "talk": ["配平自检只看三样：变价元素升降是否相等、两边原子是否相等、有无漏配的离子或分子。"], "title": "案例：配平 Al 与盐酸并核对电子守恒"}, "intro": "规律是用来预测与配平的。==氧化还原配平的核心只有一条：化合价升高总数等于降低总数，即得失电子守恒。==把这条守恒用熟，规律题和配平题是同一类题。", "learn": [{"h": "四条规律速览", "p": "**守恒律**：得失电子总数相等；**价态律**：最高价只有氧化性、最低价只有还原性、中间价两性兼有，同元素不同价态间可发生归中或歧化，但**相邻价态之间不反应**；**强弱律**：氧化剂的氧化性强于氧化产物，还原剂的还原性强于还原产物；**先后律**：多种还原剂遇一种氧化剂时，最强的先反应。\n\n==先后律的生活版：氧化剂的量不够时，先「吃掉」还原性最强的那个。=="}, {"h": "歧化与归中", "p": "**歧化**：同一元素的同一价态，一部分升高一部分降低，如 Cl₂ + 2NaOH ＝ NaCl + NaClO + H₂O，Cl 由 0 分别到 −1 与 +1。**归中**：同一元素的高价与低价向中间价靠拢，如 SO₂ + 2H₂S ＝ 3S↓ + 2H₂O，S 由 +4 与 −2 归到 0。\n\n判断前提：歧化要求该价态上下都有位置，归中要求高低价之间存在中间价，且产物价态不能越过对方（不能交叉到对面）。"}, {"h": "化合价升降法配平四步", "p": "以 Cu 与稀硝酸为例：3Cu + 8HNO₃（稀）＝ 3Cu(NO₃)₂ + 2NO↑ + 4H₂O。第一步标价：Cu 0→+2 升 2，N +5→+2 降 3；第二步求最小公倍数 6：Cu 前配 3、NO 前配 2；第三步配平其余物质：Cu(NO₃)₂ 配 3，未变价的 NO₃⁻ 有 6 个，加上生成 NO 的 2 个 N，HNO₃ 共 8；第四步配 H₂O 为 4 并查守恒。\n\n==配平顺序固定：先配变价元素，再配其余原子，最后查氧与电荷。==注意硝酸中只有一部分 N 变价，配 HNO₃ 系数时要把成盐的那部分算进去。"}, {"h": "易错提醒", "p": "易错提醒：歧化反应中氧化剂与还原剂是同一物质，比值计算要按变价原子个数拆开数，如 Cl₂ 与 NaOH 反应中作氧化剂与作还原剂的 Cl₂ 分子数之比为 1∶1。"}], "pitfalls": ["配平只配变价元素、漏配成盐部分的酸根（如硝酸总系数算少）。", "歧化反应的氧化剂还原剂比值不按变价原子拆分计算。", "归中产物价态写越界（交叉到对面）。"], "svg": "<rect x='20' y='40' width='75' height='30' rx='6' fill='#e0f2fe'/><text x='57' y='60' text-anchor='middle' font-size='12'>标价态</text><rect x='110' y='40' width='75' height='30' rx='6' fill='#e0f2fe'/><text x='147' y='60' text-anchor='middle' font-size='12'>求升降</text><rect x='200' y='40' width='75' height='30' rx='6' fill='#e0f2fe'/><text x='237' y='60' text-anchor='middle' font-size='12'>等升降配平</text><rect x='290' y='40' width='60' height='30' rx='6' fill='#dbeafe'/><text x='320' y='60' text-anchor='middle' font-size='12'>查守恒</text><text x='102' y='60' font-size='13'>→</text><text x='192' y='60' font-size='13'>→</text><text x='282' y='60' font-size='13'>→</text>", "svgCap": "化合价升降法配平四步：标价态、求升降、使升降相等、检查守恒。"}, "video": {"bvid": "BV1zK411674L", "p": 15, "t": "氧化还原反应(2)", "dur": "22:32", "from": 0, "vtop": ["得失电子守恒：化合价升高总数等于降低总数，配平从这里下手。", "氧化性还原性强弱看得失电子难易，不看得失电子多少。", "同一元素相邻价态之间不发生氧化还原反应，歧化与归中都有价态前提。"], "vsum": "氧化还原的规律题靠四条：**守恒律**（得失电子总数相等，用于配平与计算），**价态律**（元素有最高价只有氧化性、有最低价只有还原性、中间价态两性兼有；同种元素不同价态发生归中或歧化，相邻价态不反应），**强弱律**（==氧化剂的氧化性强于氧化产物==，还原剂的还原性强于还原产物，可比较强弱、判断反应能否发生），**先后律**（一种氧化剂遇到多种还原剂，先与最强的反应）。配平入门用化合价升降法：标价态、求升降、使升降总数相等，再配平其他原子并检查。\n易错提醒：配平不能只配变价元素，成盐的那部分酸根也要配进去，硝酸的总系数最容易因此算少。", "vtech": ["看到配平题 → 先用化合价升降配平变价元素，再配平其余原子，最后查 O 与电荷。", "看到强弱比较题 → 从已给方程式读：氧化剂强于氧化产物、还原剂强于还原产物。", "看到归中歧化判断 → 先看价态位置：同元素高低价可归中，同元素中间价可歧化，相邻价态不动。"], "vgaokao": []}}, "chem_c023": {"name": "含氯消毒剂的原理与安全使用", "sec": 0, "secTitle": "微项目：科学使用含氯消毒剂", "page": 76, "desc": "84 与漂白粉靠 HClO 消毒；绝不能与洁厕灵等酸性物质混用，会放出有毒 Cl₂。", "criteria": ["能复述定义和公式", "能看懂例题的每一步", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清思路"], "diag": null, "pre": ["chem_c015", "chem_c021"], "next": [], "content": {"advance": {"a": "HClO 中 +1 价的 Cl 有强氧化性：对细菌病毒，它氧化破坏蛋白质等生物大分子使其失活；对有色物质，它氧化破坏发色基团使其褪色。共同本质都是强氧化作用，代价是 Cl 由 +1 价被还原。", "kind": "self", "q": "从氧化还原角度说明：为什么 HClO 既能杀菌又能漂白？这两件事的共同本质是什么？"}, "apply": [{"ans": 2, "opts": ["把 84 与洁厕灵混合增强去污", "84 与酒精混合双倍消毒", "按说明稀释 84、戴手套、开窗通风使用", "把漂白粉放在阳台敞口保存"], "q": "下列使用消毒剂的做法正确的是（ ）", "why": "A 会生成有毒 Cl₂；B 两者大量混用有安全风险且降低效果；D 会加速漂白粉失效。C 是标准安全用法。"}], "basics": [{"ans": 1, "opts": ["NaCl、CaCl₂", "NaClO、Ca(ClO)₂", "HClO、HClO", "NaOH、Ca(OH)₂"], "q": "84 消毒液和漂白粉的有效成分分别是（ ）", "why": "84 有效成分是 NaClO，漂白粉有效成分是 Ca(ClO)₂，二者都靠转化为 HClO 起作用。"}, {"ans": 0, "opts": ["Ca(ClO)₂ 与 CO₂、H₂O 反应生成 HClO，HClO 又分解", "Ca(ClO)₂ 被氧气氧化", "CaCl₂ 潮解流失", "与 N₂ 发生反应"], "q": "漂白粉长期露置于空气中失效的原因是（ ）", "why": "Ca(ClO)₂ + CO₂ + H₂O ＝ CaCO₃ + 2HClO，HClO 见光分解，有效成分耗尽而失效。"}], "case": {"a": "ClO⁻ + Cl⁻ + 2H⁺ ＝ Cl₂↑ + H₂O；氧化剂 ClO⁻、还原剂 Cl⁻，归中反应；立即通风撤离。", "hints": ["84 的有效成分提供 ClO⁻，洁厕灵提供 H⁺ 与 Cl⁻。", "看 Cl 的价态：+1 与 −1 向 0 靠拢。"], "q": "写出 84 消毒液与洁厕灵混用放出 Cl₂ 的离子方程式，指出其中的氧化剂、还原剂与反应类型，并给出正确处置。", "steps": ["离子方程式：ClO⁻ + Cl⁻ + 2H⁺ ＝ Cl₂↑ + H₂O（查：原子 Cl 2、O 1、H 2；电荷左 −1−1+2＝0，守恒）。", "ClO⁻ 中 Cl 由 +1 降到 0，是氧化剂；Cl⁻ 中 Cl 由 −1 升到 0，是还原剂。", "同种元素高低价向中间归拢，属于归中反应。", "处置：立即停止混用、开窗通风、人员离开现场，残液大量清水冲稀。"], "talk": ["生活安全题要把方程式、概念判断、处置动作三件套答全，只写方程式不算完整。"], "title": "案例：为什么 84 和洁厕灵混用会出事"}, "intro": "微项目把全章搬进生活：消毒剂的说明书背后是胶体、氧化还原与离子反应。==一切含氯消毒剂的有效成分，最终都要靠次氯酸（HClO）的强氧化性杀菌消毒。==用对是帮手，混用可能出人命。", "learn": [{"h": "两类含氯消毒剂", "p": "**84 消毒液**的有效成分是 **NaClO**，**漂白粉**的有效成分是 **Ca(ClO)₂**（工业漂白粉是 Ca(ClO)₂、CaCl₂ 等的混合物，有效成分只认 Ca(ClO)₂）。\n\n它们本身氧化性有限，转化为 **HClO** 后消毒漂白能力大增：漂白粉在空气中靠 CO₂ 促成转化，Ca(ClO)₂ + CO₂ + H₂O ＝ CaCO₃↓ + 2HClO。"}, {"h": "HClO 为什么能消毒", "p": "HClO 中 Cl 为 **+1 价**，有强**氧化性**，能破坏细菌、病毒的蛋白质结构，还能漂白有色物质。它不稳定，见光易分解：2HClO ＝(光照) 2HCl + O₂↑。\n\n==消毒剂要密封、避光、阴凉保存，原理就是防止 HClO 提前分解、有效成分流失。==漂白粉长期露置失效，走的正是「生成 HClO 再分解」这条路。"}, {"h": "安全红线：绝不能与酸混用", "p": "84 消毒液与**洁厕灵**（主要成分盐酸）混用会发生：ClO⁻ + Cl⁻ + 2H⁺ ＝ Cl₂↑ + H₂O，生成**有毒的 Cl₂**，这正是第 3 节学过的归中反应（Cl 由 +1 与 −1 归到 0）。\n\n==含氯消毒剂不与酸性物质混用、不与酒精大量混用，使用时通风、戴手套、按比例稀释。==误混后应立即开窗通风、人员撤离，不要近距离猛吸。"}, {"h": "易错提醒", "p": "易错提醒：漂白粉的「有效成分」是 Ca(ClO)₂，不是 CaCl₂；84 的有效成分是 NaClO，不是 NaCl。考试写错有效成分，后面的方程式全盘皆错。"}], "pitfalls": ["有效成分写错（NaClO 写成 NaCl、Ca(ClO)₂ 写成 CaCl₂）。", "混用方程式电荷不守恒或漏写 H⁺ 的系数 2。", "把漂白粉失效归因于被氧气氧化（实为与 CO₂、H₂O 反应后 HClO 分解）。"], "svg": "<rect x='25' y='35' width='95' height='32' rx='6' fill='#e0f2fe'/><text x='72' y='56' text-anchor='middle' font-size='12'>NaClO / Ca(ClO)₂</text><rect x='155' y='35' width='70' height='32' rx='6' fill='#dbeafe'/><text x='190' y='56' text-anchor='middle' font-size='12'>HClO</text><rect x='260' y='35' width='80' height='32' rx='6' fill='#fee2e2'/><text x='300' y='56' text-anchor='middle' font-size='12'>强氧化消毒</text><text x='190' y='95' text-anchor='middle' font-size='11' fill='#dc2626'>+ 酸 → Cl₂↑ 有毒 绝不能混用</text><text x='137' y='56' font-size='13'>→</text><text x='242' y='56' font-size='13'>→</text>", "svgCap": "含氯消毒剂的作用链：有效成分转化为 HClO 后靠强氧化性消毒；遇酸生成 Cl₂。"}, "video": {"bvid": "BV1zK411674L", "p": 16, "t": "微项目：科学使用含氯消毒剂", "dur": "20:27", "from": 0, "vtop": ["含氯消毒剂的杀手锏都是 HClO：强氧化性杀菌漂白。", "84 消毒液（NaClO）绝不能与洁厕灵（盐酸）混用：会生成有毒的 Cl₂。", "漂白粉失效是与空气中 CO₂、H₂O 反应生成 HClO 后又分解，要密封避光保存。"], "vsum": "微项目把全章知识落到生活：84 消毒液的有效成分是 **NaClO**，漂白粉的有效成分是 **Ca(ClO)₂**，它们都要先转化为 **HClO** 才能发挥**强氧化性**消毒作用。安全红线有三条：==含氯消毒剂不能与酸性洁厕灵混用==（ClO⁻ 与 Cl⁻ 在酸性条件下生成 Cl₂，中毒事故多源于此）；不能与酒精等还原性物质大量混用；要密封、避光、低温保存防止 HClO 分解失效。使用时按说明稀释、戴手套、通风，消毒后用清水擦拭减少残留。\n易错提醒：84 消毒液的有效成分是 NaClO、漂白粉的有效成分是 Ca(ClO)₂，写成 NaCl 或 CaCl₂ 就全错了。", "vtech": ["看到消毒剂混用题 → 立刻写 ClO⁻ + Cl⁻ + 2H⁺ ＝ Cl₂↑ + H₂O，先判有毒气体再谈其他。", "看到漂白粉失效题 → 沿 Ca(ClO)₂ → HClO → 分解三步写，落点是有效成分减少。"], "vgaokao": []}}}, "units": {"u_chem_1": {"id": "u_chem_1", "name": "走进化学科学", "secs": "第1节", "pageFrom": 2, "pageTo": 9, "members": ["chem_c001", "chem_c002"], "video": {"bvid": "BV11S4y1b7eE", "p": 1, "t": "走进化学科学", "dur": "15:21", "vtop": ["化学是在原子、分子水平上研究物质的学科。", "五位科学家对应五项贡献：元素概念、质量守恒、原子论、分子学说、周期表。", "绿色化学是从源头消除污染，不是末端治理。"], "vsum": "化学史就是五级台阶：波义耳给出元素的概念，拉瓦锡用定量实验确立**质量守恒**，道尔顿提出**原子论**，阿伏加德罗提出**分子学说**，门捷列夫排出周期表。现代方向记三个词：**绿色化学**（源头减污）、纳米化学、超分子化学。==考试爱考人物与贡献的对应==，以及把末端治理冒充绿色化学的陷阱。视频为化学僧鲁科版必修一《走进化学科学》（15:21）。\n易错提醒：绿色化学指的是从源头减少或消除污染，把末端治理说成绿色化学是这类题最常见的陷阱。", "vtech": ["看到「人物—贡献」连线信号 → 先锁定最有名的周期表（门捷列夫）和质量守恒（拉瓦锡），再排其余。", "看到「尾气/废水处理后排放」→ 判断为末端治理，不是绿色化学。"], "vgaokao": [], "from": "化学僧"}}, "u_chem_2": {"id": "u_chem_2", "name": "研究物质性质的方法和程序", "secs": "第2节", "pageFrom": 10, "pageTo": 16, "members": ["chem_c003", "chem_c004"], "video": {"bvid": "BV1zK411674L", "p": 1, "t": "研究物质性质的方法和程序（一）", "dur": "20:47", "vtop": ["四种方法：观察、实验、分类、比较。", "基本程序：观察→预测→实验→结论，顺序不能乱。", "钠与氧气：常温 Na₂O（白色），加热 Na₂O₂（淡黄色）。"], "vsum": "方法四件套（观察、实验、分类、比较）加上固定程序（==观察→预测→实验→结论==），是研究任何新物质的通用打法。钠是第一个案例：保存在**煤油**中；常温被氧化成白色 **Na₂O**，加热生成淡黄色 **Na₂O₂**（氧为 −1 价，能与水、CO₂ 反应放氧，可作**供氧剂**）；与铁的比较说明金属有共性、更有个性。\n易错提醒：钠在常温下被氧化成白色 Na₂O、加热时生成淡黄色 Na₂O₂，两种产物的颜色一定要对应记准。", "vtech": ["看到排序题信号 → 默念「观察、预测、实验、结论」，预测永远在实验前。", "看到钠与氧气的题 → 先问条件：常温白色 Na₂O，加热淡黄 Na₂O₂。"], "vgaokao": [], "from": 0}}, "u_chem_3": {"id": "u_chem_3", "name": "氯气的性质", "secs": "第2节", "pageFrom": 17, "pageTo": 22, "members": ["chem_c005"], "video": {"bvid": "BV1zK411674L", "p": 2, "t": "研究物质性质的方法和程序（二）", "dur": "21:27", "vtop": ["氯气黄绿色、有毒，闻气味用飘闻法。", "与铁反应生成 FeCl₃，强氧化性。", "漂白靠 HClO；石蕊先变红后褪色。"], "vsum": "氯气：黄绿色、刺激性气味、有毒、能溶于水。与金属生成**高价盐**（Fe→**FeCl₃**，棕褐色烟），与氢气苍白色火焰生成 HCl，与水生成 HCl 和 HClO。漂白、杀菌靠 **HClO**，干燥氯气不漂白；氯水久置变稀盐酸。**新制氯水**==使石蕊先变红后褪色==，是必考现象。\n易错提醒：真正起漂白、杀菌作用的是 HClO 而不是 Cl₂，干燥的氯气本身并不漂白。", "vtech": ["看到「漂白」信号 → 答题落点写 HClO，不写 Cl₂。", "看到石蕊现象 → 分两步写：先变红（酸性）后褪色（漂白）。"], "vgaokao": [], "from": 0}}, "u_chem_4": {"id": "u_chem_4", "name": "物质的量与摩尔质量", "secs": "第3节", "pageFrom": 23, "pageTo": 27, "members": ["chem_c006", "chem_c007"], "video": {"bvid": "BV1zK411674L", "p": 3, "t": "化学中常用的物理量——物质的量（一）", "dur": "24:12", "vtop": ["n ＝ N / N_A，N_A ≈ 6.02×10²³ mol⁻¹。", "摩尔质量数值等于相对分子质量，单位 g/mol。", "换算先统一到 n 再出发。"], "vsum": "**物质的量** n 是微观粒子数的批量单位，桥梁是 N_A ≈ 6.02×10²³ mol⁻¹ 与**摩尔质量 M**（数值等于**相对分子质量**、单位 g/mol）。做题总路线：质量除以 M、==个数除以 N_A，先都换成 n==；求复合粒子（分子中的原子、离子所带电荷等）记得乘**化学式下标**。说「1 mol」必须指明粒子种类。\n易错提醒：求分子中的原子、离子所带电荷等复合粒子的数目时，一定要记得乘化学式中的下标。", "vtech": ["看到质量/个数混合换算 → 全部先换成 n（m÷M、N÷N_A）再求目标。", "看到「分子中原子数」 → 分子 mol 先算，再乘下标。"], "vgaokao": [], "from": 0}}, "u_chem_5": {"id": "u_chem_5", "name": "气体摩尔体积", "secs": "第3节", "pageFrom": 28, "pageTo": 30, "members": ["chem_c008"], "video": {"bvid": "BV1zK411674L", "p": 4, "t": "化学中常用的物理量——物质的量（二）", "dur": "20:22", "vtop": ["22.4 L/mol 只限标准状况下的气体。", "同温同压：体积比＝物质的量比＝分子数比。", "密度比＝摩尔质量比。"], "vsum": "**气体摩尔体积** V_m：标况下约 **22.4 L/mol**，前提是「气体」加「**标准状况**」，缺一不可（水、苯、SO₃ 在标况都不是气体）。**阿伏加德罗定律**：同温同压下体积比＝物质的量比＝分子数比；==密度比＝摩尔质量比==。常温常压下 1 mol 气体约 24.5 L，不要和 22.4 混。\n易错提醒：22.4 L/mol 只适用于标准状况下的气体，非标况或非气体硬套这个数值是这类题最常见的丢分点。", "vtech": ["看到 22.4 → 先核两件事：气体？标况？有一个不满足就停手。", "看到「同温同压求密度比/求 M」 → 直接写 ρ 比 ＝ M 比。"], "vgaokao": [], "from": 0}}, "u_chem_6": {"id": "u_chem_6", "name": "物质的量浓度与配制", "secs": "第3节", "pageFrom": 31, "pageTo": 33, "members": ["chem_c009", "chem_c010"], "video": {"bvid": "BV1zK411674L", "p": 5, "t": "化学中常用的物理量——物质的量（三）", "dur": "23:37", "vtop": ["c ＝ n / V，V 是溶液体积不是溶剂体积。", "配制八步：计算、称量、溶解、转移、洗涤、定容、摇匀、装瓶。", "误差分析只看 n 和 V 谁变了。"], "vsum": "**物质的量浓度 c ＝ n / V**，==V 指溶液体积；溶液均一==，取出部分浓度不变；**离子浓度乘下标**。配制用**容量瓶**（就近选大、用前查漏、不能溶解和存放），八步里最易丢分的是：冷却后再转移、洗涤 2~3 次并转入、**平视定容**、摇匀后不补水。误差分析回到 c＝n/V：n 变小或 V 变大→偏低，反之偏高。\n易错提醒：公式中的 V 指的是溶液体积而不是溶剂体积，代错了浓度必然算错。", "vtech": ["看到误差分析 → 只问两句：溶质少了吗？水多了还是少了？对照 c＝n/V 定偏高偏低。", "看到「溶于 1 L 水」 → 警惕：那不是溶液体积，不能直接当 V。"], "vgaokao": [], "from": 0}}, "u_chem_7": {"id": "u_chem_7", "name": "微项目：探秘膨松剂", "secs": "微项目", "pageFrom": 34, "pageTo": 36, "members": ["chem_c011"], "video": {"bvid": "BV1zK411674L", "p": 6, "t": "微项目：探秘膨松剂", "dur": "21:02", "vtop": ["NaHCO₃ 受热、遇酸都放出 CO₂。", "受热分解计量比 2∶1，遇酸 1∶1。", "探究程序与第 2 节的四步完全一致。"], "vsum": "微项目用 **NaHCO₃** 收官全章：受热分解 2NaHCO₃ ＝ Na₂CO₃ + H₂O + CO₂↑（膨松），遇酸 NaHCO₃ + HCl ＝ NaCl + H₂O + CO₂↑（中和胃酸）。探究流程正是第 2 节的四步程序，计算正是第 3 节的**计量换算**——==方法与定量在本课合流==。注意**碳酸钠（苏打）**与**碳酸氢钠（小苏打）**不要写混。\n易错提醒：碳酸钠是苏打、碳酸氢钠是小苏打，两者的俗名和化学式千万不要写混。", "vtech": ["看到方程式计算 → 先把已知量换成 mol，按计量数比例推目标物，再换单位。", "看到俗名（小苏打/苏打） → 先翻译成化学式再动笔。"], "vgaokao": [], "from": 0}}, "u_chem_8": {"id": "u_chem_8", "name": "元素与物质分类", "secs": "第1节", "pageFrom": 44, "pageTo": 48, "members": ["chem_c012", "chem_c013"], "video": {"bvid": "BV1zK411674L", "p": 8, "t": "元素与物质分类(1)", "dur": "20:27", "from": 0, "vtop": ["元素是质子数（核电荷数）相同的一类原子的总称，只论种类不论个数。", "同一元素可以组成不同单质（同素异形体），也可以进入多种化合物。", "分类先看组成：单质只含一种元素，化合物含两种或两种以上元素。"], "vsum": "本课先立元素观：**元素**是质子数相同的一类原子的总称，物质由元素组成，元素在物质中以游离态（单质）或化合态（化合物）存在；金刚石与石墨、氧气与臭氧是**同素异形体**。再学两种分类法：**树状分类**把物质层层分成纯净物与混合物、单质与化合物、氧化物酸碱盐；**交叉分类**从多个角度给同一物质贴标签，如 Na₂CO₃ 既是盐、又是钠盐、又是碳酸盐。判分类题先抓定义边界：==氧化物只含两种元素且一种是氧==，酸电离出的阳离子全是 H⁺，碱电离出的阴离子全是 OH⁻。\n易错提醒：元素只论种类、不论个数，描述物质组成时给元素带上数字是最常见的错误。", "vtech": ["看到分类判断题 → 先写定义再对号：氧化物数元素种类（两种、含氧），酸碱盐看电离出的离子。", "看到「某物质属于哪几类」 → 用交叉分类多角度贴标签，别只答一个类别。"], "vgaokao": []}}, "u_chem_9": {"id": "u_chem_9", "name": "分散系与胶体", "secs": "第1节", "pageFrom": 49, "pageTo": 52, "members": ["chem_c014", "chem_c015"], "video": {"bvid": "BV1zK411674L", "p": 10, "t": "元素与物质分类(3)", "dur": "20:02", "from": 0, "vtop": ["分散系分类只看分散质粒子大小：小于 1 nm、1~100 nm、大于 100 nm。", "丁达尔效应是胶体的光学性质，是鉴别胶体与溶液最常用的方法。", "Fe(OH)₃ 胶体制备要煮沸、不能搅拌、不能加热过度。"], "vsum": "分散系是被分散的物质（**分散质**）分散在另一种物质（**分散剂**）中形成的混合物。按分散质粒子直径分：溶液小于 1 nm（均一稳定、能透过滤纸和**半透膜**），胶体 1~100 nm（较稳定、能透过滤纸不能透过半透膜），浊液大于 100 nm（不稳定、静置分层或沉降）。==胶体的招牌性质是丁达尔效应==；Fe(OH)₃ 胶体由饱和 FeCl₃ 溶液滴入沸水制得，能吸附悬浮物净水，加电解质、加热或加带相反电荷的胶体都会**聚沉**。\n易错提醒：区分溶液、胶体与浊液的本质是分散质粒子直径的大小，丁达尔效应只是胶体的性质而不是本质区别。", "vtech": ["看到鉴别胶体与溶液 → 首选丁达尔效应：一束光侧面看，胶体有光亮通路。", "看到粒子大小比较题 → 先把单位统一到 nm，再按 1 与 100 两个界限归类。"], "vgaokao": []}}, "u_chem_10": {"id": "u_chem_10", "name": "电解质与电离", "secs": "第2节", "pageFrom": 53, "pageTo": 58, "members": ["chem_c016", "chem_c017"], "video": {"bvid": "BV1zK411674L", "p": 11, "t": "电解质的电离 离子反应(1)", "dur": "20:17", "from": 0, "vtop": ["电解质与非电解质都是化合物，单质和混合物既不是电解质也不是非电解质。", "导电必须靠化合物自身电离出的离子，SO₂、NH₃ 的水溶液导电但它们是非电解质。", "强电解质完全电离用等号，弱电解质部分电离用可逆号。"], "vsum": "**电解质**：在水溶液里或熔融状态下能够导电的化合物；**非电解质**：在水溶液里和熔融状态下都不能导电的化合物。两个限定缺一不可——对象必须是化合物，==导电必须靠自身电离==。**强电解质**（强酸、强碱、大多数盐）完全电离，书写用等号；**弱电解质**（弱酸、弱碱、水）部分电离，用可逆号，多元弱酸分步电离、多元弱碱一步写。酸式盐的电离要分强弱：NaHSO₄ 在水中完全电离出 H⁺，NaHCO₃ 中的 HCO₃⁻ 只微弱电离。\n易错提醒：SO₂、CO₂、NH₃ 的水溶液虽然能导电，但导电靠的是它们与水反应生成的酸或碱电离，它们本身不是电解质。", "vtech": ["看到导电判断 → 连问三句：是化合物吗？导电靠自身电离吗？熔融时导电吗？", "看到电离方程式 → 先定强弱：强用等号全拆，弱用可逆号，多元弱酸分步。"], "vgaokao": []}}, "u_chem_11": {"id": "u_chem_11", "name": "离子反应与离子方程式", "secs": "第2节", "pageFrom": 59, "pageTo": 65, "members": ["chem_c018", "chem_c019"], "video": {"bvid": "BV1zK411674L", "p": 12, "t": "电解质的电离 离子反应(2)", "dur": "20:28", "from": 0, "vtop": ["离子方程式四步：写、拆、删、查（查原子守恒与电荷守恒）。", "能拆的只有强酸、强碱和可溶性盐；沉淀、气体、水、弱电解质、氧化物都不拆。", "离子不能大量共存的四种情形：生成沉淀、气体、水（或弱电解质）、发生氧化还原反应。"], "vsum": "**离子反应**是电解质在溶液中以离子形式参与的反应，==离子方程式只写实际参与反应的离子==。书写四步：写出化学方程式；把**强酸、强碱、可溶性盐**拆成离子，难溶物、气体、水、弱电解质、单质、氧化物保留化学式；删去两边相同的离子；检查**原子守恒**、**电荷守恒**和最简整数比。离子共存抓四条禁令，离子检验抓试剂与现象的对应：如 SO₄²⁻ 用盐酸酸化后加 BaCl₂，Cl⁻ 用 AgNO₃ 与稀硝酸，NH₄⁺ 用浓 NaOH 加热并用湿润红色石蕊试纸检验。\n易错提醒：检验 SO₄²⁻ 时要先加盐酸酸化排除 CO₃²⁻ 等干扰，再加 BaCl₂ 观察白色沉淀。", "vtech": ["写离子方程式 → 默念「写拆删查」，最后一步专门查电荷是否守恒、最简比是否约掉。", "看到离子共存题 → 按沉淀、气体、水、氧化还原四张清单逐对排查。", "看到「与量有关」的离子反应 → 先判断谁过量，过量者满足化学计量、少量者完全反应。"], "vgaokao": []}}, "u_chem_12": {"id": "u_chem_12", "name": "氧化还原反应的基本概念", "secs": "第3节", "pageFrom": 66, "pageTo": 71, "members": ["chem_c020", "chem_c021"], "video": {"bvid": "BV1zK411674L", "p": 14, "t": "氧化还原反应(1)", "dur": "23:17", "from": 0, "vtop": ["氧化还原反应的本质是电子转移，特征是元素化合价发生变化。", "口诀连对象记：升（化合价升高）失（失电子）氧（被氧化、是还原剂）。", "四种基本反应类型与氧化还原有交叉：置换一定是，化合分解部分是，复分解一定不是。"], "vsum": "氧化还原反应以==化合价升降为特征、以电子转移为本质==。判断三步：标化合价、看升降、定概念——化合价升高、失去电子、被氧化、该物质是**还原剂**、对应氧化产物；化合价降低、得到电子、被还原、该物质是**氧化剂**、对应还原产物。**双线桥**从反应物指向产物，桥上写清得失电子数与化合价变化。常见氧化剂有浓硫酸、硝酸、KMnO₄、Cl₂、Fe³⁺ 等，常见还原剂有金属单质、C、H₂、CO、Fe²⁺、S²⁻ 等，**中间价态**物质如 Fe²⁺、SO₂ 既有氧化性又有还原性。\n易错提醒：还原剂被氧化、氧化剂被还原，「剂」的名称与它自身发生的反应正好相反，最容易记反。", "vtech": ["看到氧化还原判断 → 先标化合价，有升有降才是；只有升或只有降的题干必有错。", "看到概念辨析 → 沿一条线走完：价态变化→得失电子→被氧化被还原→剂与产物，别跳步。"], "vgaokao": []}}, "u_chem_13": {"id": "u_chem_13", "name": "氧化还原反应的规律", "secs": "第3节", "pageFrom": 72, "pageTo": 75, "members": ["chem_c022"], "video": {"bvid": "BV1zK411674L", "p": 15, "t": "氧化还原反应(2)", "dur": "22:32", "from": 0, "vtop": ["得失电子守恒：化合价升高总数等于降低总数，配平从这里下手。", "氧化性还原性强弱看得失电子难易，不看得失电子多少。", "同一元素相邻价态之间不发生氧化还原反应，歧化与归中都有价态前提。"], "vsum": "氧化还原的规律题靠四条：**守恒律**（得失电子总数相等，用于配平与计算），**价态律**（元素有最高价只有氧化性、有最低价只有还原性、中间价态两性兼有；同种元素不同价态发生归中或歧化，相邻价态不反应），**强弱律**（==氧化剂的氧化性强于氧化产物==，还原剂的还原性强于还原产物，可比较强弱、判断反应能否发生），**先后律**（一种氧化剂遇到多种还原剂，先与最强的反应）。配平入门用化合价升降法：标价态、求升降、使升降总数相等，再配平其他原子并检查。\n易错提醒：配平不能只配变价元素，成盐的那部分酸根也要配进去，硝酸的总系数最容易因此算少。", "vtech": ["看到配平题 → 先用化合价升降配平变价元素，再配平其余原子，最后查 O 与电荷。", "看到强弱比较题 → 从已给方程式读：氧化剂强于氧化产物、还原剂强于还原产物。", "看到归中歧化判断 → 先看价态位置：同元素高低价可归中，同元素中间价可歧化，相邻价态不动。"], "vgaokao": []}}, "u_chem_14": {"id": "u_chem_14", "name": "微项目：科学使用含氯消毒剂", "secs": "微项目", "pageFrom": 76, "pageTo": 78, "members": ["chem_c023"], "video": {"bvid": "BV1zK411674L", "p": 16, "t": "微项目：科学使用含氯消毒剂", "dur": "20:27", "from": 0, "vtop": ["含氯消毒剂的杀手锏都是 HClO：强氧化性杀菌漂白。", "84 消毒液（NaClO）绝不能与洁厕灵（盐酸）混用：会生成有毒的 Cl₂。", "漂白粉失效是与空气中 CO₂、H₂O 反应生成 HClO 后又分解，要密封避光保存。"], "vsum": "微项目把全章知识落到生活：84 消毒液的有效成分是 **NaClO**，漂白粉的有效成分是 **Ca(ClO)₂**，它们都要先转化为 **HClO** 才能发挥**强氧化性**消毒作用。安全红线有三条：==含氯消毒剂不能与酸性洁厕灵混用==（ClO⁻ 与 Cl⁻ 在酸性条件下生成 Cl₂，中毒事故多源于此）；不能与酒精等还原性物质大量混用；要密封、避光、低温保存防止 HClO 分解失效。使用时按说明稀释、戴手套、通风，消毒后用清水擦拭减少残留。\n易错提醒：84 消毒液的有效成分是 NaClO、漂白粉的有效成分是 Ca(ClO)₂，写成 NaCl 或 CaCl₂ 就全错了。", "vtech": ["看到消毒剂混用题 → 立刻写 ClO⁻ + Cl⁻ + 2H⁺ ＝ Cl₂↑ + H₂O，先判有毒气体再谈其他。", "看到漂白粉失效题 → 沿 Ca(ClO)₂ → HClO → 分解三步写，落点是有效成分减少。"], "vgaokao": []}}}, "nodeUnit": {"chem_c001": "u_chem_1", "chem_c002": "u_chem_1", "chem_c003": "u_chem_2", "chem_c004": "u_chem_2", "chem_c005": "u_chem_3", "chem_c006": "u_chem_4", "chem_c007": "u_chem_4", "chem_c008": "u_chem_5", "chem_c009": "u_chem_6", "chem_c010": "u_chem_6", "chem_c011": "u_chem_7", "chem_c012": "u_chem_8", "chem_c013": "u_chem_8", "chem_c014": "u_chem_9", "chem_c015": "u_chem_9", "chem_c016": "u_chem_10", "chem_c017": "u_chem_10", "chem_c018": "u_chem_11", "chem_c019": "u_chem_11", "chem_c020": "u_chem_12", "chem_c021": "u_chem_12", "chem_c022": "u_chem_13", "chem_c023": "u_chem_14"}};

window.SELF_VIDEO_PACKS=(window.SELF_VIDEO_PACKS||[]);window.SELF_VIDEO_PACKS.push({"BV11S4y1b7eE|1": {"src": "/video/chem1.mp4", "vtt": "/video/chem1.vtt", "segs": [[0, "开场导入：从生活中的物质走进化学科学"], [124, "古代化学：用其物而不知其理（火、陶瓷、冶炼、炼丹）"], [156, "近代化学形成：波义耳、拉瓦锡、道尔顿、阿伏加德罗、门捷列夫"], [259, "我国化学成就：国家最高科学技术奖与屠呦呦"], [364, "化学的特征一：从宏观与微观两个角度认识物质"], [386, "特征二：用符号表征物质（元素符号、化学式、方程式）"], [485, "特征三：在不同层面创造物质（提取、合成、新物质）"], [605, "化学的价值与探索空间：能源、材料、环境、生命、信息"], [734, "随堂检测：三道题练手"], [855, "课堂小结：形成发展、主要特征、探索空间"]]}});
